import pandas as pd
from sklearn.cluster import KMeans
import matplotlib.pyplot as plt

# Load your orders.csv
df = pd.read_csv("orders.csv")

# Example: if your CSV has customer_id, price, quantity
df["revenue"] = df["Amount"] * df["Quantity"]

# Aggregate per customer
customer_df = df.groupby("CustomerID").agg({
    "OrderID": "count",
    "Amount": "sum",
    "Quantity": "sum"
}).reset_index()

# Select features for clustering
X = customer_df[["OrderID", "Amount", "Quantity"]]

# Apply KMeans clustering
kmeans = KMeans(n_clusters=3, random_state=42)
customer_df["cluster"] = kmeans.fit_predict(X)

print(customer_df.head())

# Visualize clusters
plt.scatter(customer_df["Amount"], customer_df["OrderID"], c=customer_df["cluster"], cmap="viridis")
plt.xlabel("Total Revenue")
plt.ylabel("Number of Orders")
plt.title("Customer Segmentation")
plt.show()



