import pandas as pd
import numpy as np
from sklearn.linear_model import LinearRegression
import matplotlib.pyplot as plt

# Suppose your df has just 'revenue' column
# Create a day index
df = df.reset_index(drop=True)  # Ensure consecutive index
df['day'] = np.arange(1, len(df) + 1)

# Features and target
X = df[['day']]  # Day number as feature
y = df['revenue']

# Train regression model
model = LinearRegression()
model.fit(X, y)

# Forecast next 60 days
future_days = np.arange(len(df) + 1, len(df) + 61).reshape(-1, 1)
forecast = model.predict(future_days)

# Plot actual vs forecast
plt.figure(figsize=(12,6))
plt.plot(df['day'], y, label='Actual Revenue')
plt.plot(future_days, forecast, label='Forecast Revenue', color='red')
plt.xlabel('Day Number')
plt.ylabel('Revenue')
plt.title('Revenue Forecast Using Linear Regression ')
plt.legend()
plt.show()

import pandas as pd
from sklearn.model_selection import train_test_split
from sklearn.ensemble import RandomForestClassifier
from sklearn.metrics import accuracy_score

# Example: your df has columns customer_id, revenue, order_id, quantity
# Create aggregated customer data
cust_data = df.groupby("CustomerID").agg({
    "Amount": "sum",
    "OrderID": "count",
    "Quantity": "sum"
}).reset_index()

# Create a churn label based on low engagement (example: customers with few orders or low revenue)
# Here, we arbitrarily define churn as revenue < median revenue OR order count < median
median_revenue = cust_data['Amount'].median()
median_orders = cust_data['OrderID'].median()

cust_data['churn'] = ((cust_data['Amount'] < median_revenue) |
                      (cust_data['OrderID'] < median_orders)).astype(int)

# Features and target
X = cust_data[['Amount','OrderID','Quantity']]
y = cust_data['churn']

# Split data
X_train, X_test, y_train, y_test = train_test_split(X, y, test_size=0.3, random_state=42)

# Train model
model = RandomForestClassifier(random_state=42)
model.fit(X_train, y_train)

# Predict and evaluate
preds = model.predict(X_test)
print("Accuracy:", accuracy_score(y_test, preds))

import pandas as pd
from sklearn.cluster import KMeans
import matplotlib.pyplot as plt

# Assume df has columns: customer_id, sku, quantity

# Step 1: Create customer-product matrix
cust_prod_matrix = df.pivot_table(index='CustomerID', columns='SKU', values='Quantity', fill_value=0)

# Step 2: Apply KMeans clustering on customers
kmeans = KMeans(n_clusters=5, random_state=42)
cust_prod_matrix['cluster'] = kmeans.fit_predict(cust_prod_matrix)

# Step 3: Visualize clusters (optional, using first 2 PCA components)
from sklearn.decomposition import PCA

pca = PCA(n_components=2)
components = pca.fit_transform(cust_prod_matrix.drop('cluster', axis=1))
plt.scatter(components[:,0], components[:,1], c=cust_prod_matrix['cluster'], cmap='viridis')
plt.xlabel('PCA Component 1')
plt.ylabel('PCA Component 2')
plt.title('Customer Segments based on purchase behavior')
plt.show()

# Step 4: Access cluster assignments
print(cust_prod_matrix['cluster'].value_counts())

import pandas as pd
from sklearn.model_selection import train_test_split
from sklearn.ensemble import RandomForestClassifier
from sklearn.metrics import accuracy_score
import glob
import os

# Path where all CSVs are stored
csv_folder = r"C:\EY_hackathon\csv_files"
csv_files = glob.glob(os.path.join(csv_folder, "*.csv"))

results = {}  # Store results for each CSV
output_folder = r"C:\EY_hackathon\output_csv_folder"
os.makedirs(output_folder, exist_ok=True)

for file in csv_files:
    df = pd.read_csv(file)

    if 'CustomerID' not in df.columns:
        print(f"Skipping {os.path.basename(file)} (no CustomerID)")
        continue

    print(f"\nProcessing {os.path.basename(file)}...")

    # Ensure columns exist
    for col in ['Amount', 'OrderID', 'Quantity']:
        if col not in df.columns:
            df[col] = 0

    # Aggregate customer data
    cust_data = df.groupby("CustomerID").agg({
        "Amount": "sum",
        "OrderID": "count",
        "Quantity": "sum"
    }).reset_index()

    # Create churn label
    median_revenue = cust_data['Amount'].median()
    median_orders = cust_data['OrderID'].median()
    cust_data['churn'] = ((cust_data['Amount'] < median_revenue) |
                          (cust_data['OrderID'] < median_orders)).astype(int)

    # Features and target
    X = cust_data[['Amount','OrderID','Quantity']]
    y = cust_data['churn']

    # Train-test split
    X_train, X_test, y_train, y_test = train_test_split(X, y, test_size=0.3, random_state=42)

    # Random Forest model
    model = RandomForestClassifier(random_state=42)
    model.fit(X_train, y_train)

    # Predict & evaluate
    preds = model.predict(X_test)
    acc = accuracy_score(y_test, preds)
    print(f"Accuracy: {acc:.2f}")

    # Save results in results dictionary
    cust_data['predicted_churn'] = model.predict(X)
    results[file] = cust_data

    # Optional: print first 5 rows to see output immediately
    print("Sample processed data:")
    print(cust_data.head())

# Save all processed CSVs after processing all files
for file, df_res in results.items():
    out_path = os.path.join(output_folder, f"processed_{os.path.basename(file)}")
    df_res.to_csv(out_path, index=False)
    print(f"Saved processed file: {out_path}")

