from gtts import gTTS
from IPython.display import Audio

def speak(text):
    tts = gTTS(text=text, lang='ml')
    tts.save("temp.mp3")
    return Audio("temp.mp3", autoplay=True)

# Example
speak("chup kar gitthi boni")

import nltk
from nltk.chat.util import Chat, reflections

# Pairs = pattern → response
pairs = [
    [r"hi|hello|hey", ["Hello! How can I help you today?", "Hey there!"]],
    [r"what is your name?", ["I'm your AI chatbot."]],
    [r"how are you?", ["I'm doing great! How about you?"]],
    [r"i am fine|good", ["Glad to hear that!", "Awesome!"]],
    [r"bye|quit|exit", ["Goodbye! Have a great day!", "See you soon!"]],
]

# Create chatbot
chatbot = Chat(pairs, reflections)

print("🤖 AI Chatbot: Hello! Type 'quit' to exit.")

# Start conversation
chatbot.converse()

