# Load files
# -------------------------------
logs = pd.read_csv("inventory_logs.csv")   # Transaction logs
products = pd.read_csv("products.csv")     # Master data with SKU, Name, NextRestockDate, ManagerEmail

# -------------------------------
# Compute current stock from logs
# -------------------------------
# Sum all quantities (sales = negative, restock = positive)
stock_summary = logs.groupby("SKU")["Quantity"].sum().reset_index()
stock_summary.rename(columns={"Quantity": "Stock"}, inplace=True)

# Merge with master product data
inventory = pd.merge(products, stock_summary, on="SKU", how="left")
inventory["Stock"] = inventory["Stock"].fillna(0)  # If no transactions exist yet

# -------------------------------
# Restock Reminders
# -------------------------------
today = datetime.today().date()

for _, row in inventory.iterrows():
    try:
        restock_date = datetime.strptime(row["NextRestockDate"], "%Y-%m-%d").date()
        # Send reminder 1 day before restock
        if restock_date - today <= timedelta(days=1):
            send_email(
                row["ManagerEmail"],
                f"Upcoming Restock Reminder: {row['Name']}",
                f"Item {row['Name']} is scheduled to be restocked on {row['NextRestockDate']}.\n"
                f"Current stock level: {row['Stock']}"
            )
    except Exception as e:
        print(f"⚠️ Skipping restock check for {row['Name']}: {e}")

import pandas as pd
from datetime import datetime, timedelta

# -------------------------------
# Sample email function (simulation)
# -------------------------------
def send_email(to_email, subject, body):
    print(f"Sending email to {to_email}")
    print(f"Subject: {subject}")
    print(f"Body: {body}")
    print("-"*50)
    # For real emails, integrate with smtplib, SendGrid, or Twilio

# -------------------------------
# Load files
# -------------------------------
logs = pd.read_csv("inventory_logs.csv")   # Transaction logs
products = pd.read_csv("products.csv")     # Master data with SKU, Name, NextRestockDate, ManagerEmail

# -------------------------------
# Standardize column names
# -------------------------------
products.columns = [col.strip() for col in products.columns]  # remove spaces
logs.columns = [col.strip() for col in logs.columns]

# Optional: rename known variations to expected names
rename_map = {
    'next_restock_date': 'NextRestockDate',
    'Next_Restock_Date': 'NextRestockDate',
    'manager_email': 'ManagerEmail',
    'Manager_Email': 'ManagerEmail'
}
products.rename(columns=rename_map, inplace=True)

# -------------------------------
# Compute current stock from logs
# -------------------------------
# Sum all quantities (sales = negative, restock = positive)
stock_summary = logs.groupby("SKU")["Quantity"].sum().reset_index()
stock_summary.rename(columns={"Quantity": "Stock"}, inplace=True)

# Merge with master product data
inventory = pd.merge(products, stock_summary, on="SKU", how="left")
inventory["Stock"] = inventory["Stock"].fillna(0)  # If no transactions exist yet

# -------------------------------
# Restock Reminders
# -------------------------------
today = datetime.today().date()

for _, row in inventory.iterrows():
    restock_date_str = row.get("NextRestockDate")

    if pd.isna(restock_date_str) or restock_date_str == "":
        print(f"⚠️ Skipping restock check for {row['Name']}: NextRestockDate missing")
        continue

    try:
        restock_date = datetime.strptime(str(restock_date_str), "%Y-%m-%d").date()
    except Exception as e:
        print(f"⚠️ Skipping restock check for {row['Name']}: Invalid date format ({restock_date_str})")
        continue

    # Send reminder 1 day before restock
    if restock_date - today <= timedelta(days=1):
        send_email(
            row["ManagerEmail"],
            f"Upcoming Restock Reminder: {row['Name']}",
            f"Item {row['Name']} is scheduled to be restocked on {restock_date_str}.\n"
            f"Current stock level: {row['Stock']}"
        )

