import pandas as pd

# -------------------------------
# Load data
# -------------------------------
logs = pd.read_csv("inventory_logs.csv")  # Columns: SKU, Quantity
products = pd.read_csv("products.csv")    # Columns: SKU, Name

# Clean column names
logs.columns = logs.columns.str.strip()
products.columns = products.columns.str.strip()

# -------------------------------
# Sort logs and calculate cumulative stock per SKU
# -------------------------------
logs['CumulativeStock'] = logs.groupby('SKU')['Quantity'].cumsum()

# -------------------------------
# Detect anomalies in cumulative stock
# -------------------------------
# Example rules:
# 1. Stock drops below 0
# 2. Stock decreases by more than 50% in a single transaction

def detect_anomaly(df):
    df = df.copy()
    df['PrevStock'] = df['CumulativeStock'].shift(1).fillna(0)
    df['StockChange'] = df['CumulativeStock'] - df['PrevStock']
    df['Anomaly'] = (df['CumulativeStock'] < 0) | (df['StockChange'] < -0.5*df['PrevStock'])
    return df

anomaly_df = logs.groupby('SKU').apply(detect_anomaly).reset_index(drop=True)

# Merge with product names
anomalies = anomaly_df[anomaly_df['Anomaly']].merge(products, on='SKU', how='left')

# -------------------------------
# Display anomalies
# -------------------------------
print("Anomalous transactions based on stock changes:")
print(anomalies[['SKU', 'Name', 'Quantity', 'CumulativeStock', 'PrevStock', 'StockChange']])

