# omnichannel_agents.py
"""
Omnichannel Conversational Agent (FastAPI)

Features:
- Create and persist sessions (SQLite)
- Switch channels (web, whatsapp, kiosk, voice) while keeping context
- /chat endpoint accepts session_id (or creates new session) and preserves conversation history
- Simple intent routing sample (greeting, search, add-to-cart, show-cart, checkout)
- Hooks (placeholders) where you can call your Recommendation / Inventory / Payment worker agents

Run:
    pip install fastapi uvicorn
    uvicorn omnichannel_agents:app --reload --port 8000
"""
from fastapi import FastAPI, HTTPException
from pydantic import BaseModel
from typing import Optional, List, Dict, Any
import sqlite3
import json
import uuid
from datetime import datetime

DB = "sessions.db"
CHANNELS = {"web", "whatsapp", "telegram", "kiosk", "voice", "mobile"}

app = FastAPI(title="Omnichannel Conversational Agent")

# ---------------------------
# SQLite helpers (simple)
# ---------------------------
def init_db():
    conn = sqlite3.connect(DB)
    cur = conn.cursor()
    cur.execute(
        """
        CREATE TABLE IF NOT EXISTS sessions (
            session_id TEXT PRIMARY KEY,
            data TEXT,
            updated_at TEXT
        )
        """
    )
    conn.commit()
    conn.close()

def save_session_to_db(session: dict):
    conn = sqlite3.connect(DB)
    cur = conn.cursor()
    sid = session["session_id"]
    data_json = json.dumps(session, default=str)
    updated_at = datetime.utcnow().isoformat()
    cur.execute(
        "INSERT OR REPLACE INTO sessions(session_id, data, updated_at) VALUES (?, ?, ?)",
        (sid, data_json, updated_at),
    )
    conn.commit()
    conn.close()

def load_session_from_db(session_id: str) -> Optional[dict]:
    conn = sqlite3.connect(DB)
    cur = conn.cursor()
    cur.execute("SELECT data FROM sessions WHERE session_id = ?", (session_id,))
    row = cur.fetchone()
    conn.close()
    if not row:
        return None
    return json.loads(row[0])

# init DB on import
init_db()

# ---------------------------
# Models
# ---------------------------
class CreateSessionRequest(BaseModel):
    customer_id: Optional[str] = None
    channel: Optional[str] = "web"
    metadata: Optional[dict] = None

class SwitchChannelRequest(BaseModel):
    channel: str

class ChatRequest(BaseModel):
    session_id: Optional[str] = None
    channel: Optional[str] = "web"
    customer_id: Optional[str] = None
    message: str

# ---------------------------
# Session utilities
# ---------------------------
def new_session(customer_id: Optional[str], channel: str, metadata: Optional[dict] = None):
    sid = str(uuid.uuid4())[:8]
    session = {
        "session_id": sid,
        "customer_id": customer_id,
        "channel": channel,
        "metadata": metadata or {},
        "created_at": datetime.utcnow().isoformat(),
        "last_active_at": datetime.utcnow().isoformat(),
        "conversation": [],   # list of {"role":"user"|"agent","channel":..., "text":..., "ts":...}
        "context": {},        # arbitrary dict where agents store context (cart, last_recs etc.)
    }
    save_session_to_db(session)
    return session

def update_session_activity(session: dict, role: str, text: str, channel: str):
    msg = {"role": role, "text": text, "channel": channel, "ts": datetime.utcnow().isoformat()}
    session.setdefault("conversation", []).append(msg)
    session["last_active_at"] = datetime.utcnow().isoformat()
    save_session_to_db(session)

# ---------------------------
# Simple worker placeholders
# Replace/extend these with your real implementations
# ---------------------------
def recommend_products_stub(session: dict, message: str, topk=3):
    """
    Very small rule-based recommender placeholder.
    Replace this with a call to your recommendation worker (ML model/api).
    """
    # check last category mentioned in message
    msg = message.lower()
    sample_catalog = [
        {"sku":"P001","name":"Denim Jacket","category":"Jackets","price":2499, "image":"https://example.com/images/denim_jacket.jpg"},
        {"sku":"P002","name":"White Tee","category":"T-Shirts","price":499, "image":"https://example.com/images/white_tee.jpg"},
        {"sku":"P003","name":"Black Sneakers","category":"Shoes","price":3499, "image":"https://example.com/images/black_sneakers.jpg"},
        {"sku":"P004","name":"Floral Dress","category":"Dresses","price":1999, "image":"https://example.com/images/floral_dress.jpg"},
    ]
    # naive category match
    for item in sample_catalog:
        if item["category"].lower() in msg or item["name"].split()[0].lower() in msg:
            return sample_catalog[:topk]
    return sample_catalog[:topk]

def check_inventory_stub(sku: str, prefer_store: Optional[str] = None):
    """
    Replace with call to your inventory worker / API.
    """
    stock_map = {"P001":5, "P002":50, "P003":2, "P004":0}
    return {"sku": sku, "total_qty": stock_map.get(sku, 0), "locations":[{"location":"WH1","qty":stock_map.get(sku,0)}]}

def process_payment_stub(amount: float, method: str, details: Optional[dict] = None):
    """
    Replace with real payment gateway integration or your payment-agent endpoint.
    This stub always succeeds except if method == 'card' and card_number endswith '0'
    """
    if method == "card" and details and details.get("card_number","").endswith("0"):
        return {"status":"failed","reason":"card_declined"}
    return {"status":"success","tx_id": str(uuid.uuid4())[:10], "amount": amount}

# ---------------------------
# Endpoints
# ---------------------------

@app.post("/session", summary="Create a new session")
def create_session(req: CreateSessionRequest):
    chan = req.channel or "web"
    if chan not in CHANNELS:
        raise HTTPException(status_code=400, detail=f"Invalid channel. Allowed: {CHANNELS}")
    session = new_session(req.customer_id, chan, req.metadata)
    return {"session_id": session["session_id"], "session": session}

@app.get("/session/{session_id}", summary="Get session data")
def get_session(session_id: str):
    s = load_session_from_db(session_id)
    if not s:
        raise HTTPException(status_code=404, detail="Session not found")
    return s

@app.post("/session/{session_id}/switch", summary="Switch channel for a session")
def switch_channel(session_id: str, req: SwitchChannelRequest):
    if req.channel not in CHANNELS:
        raise HTTPException(status_code=400, detail=f"Invalid channel. Allowed: {CHANNELS}")
    s = load_session_from_db(session_id)
    if not s:
        raise HTTPException(status_code=404, detail="Session not found")
    s["channel"] = req.channel
    s["metadata"]["last_switched_to"] = req.channel
    s["last_active_at"] = datetime.utcnow().isoformat()
    save_session_to_db(s)
    return {"message": f"Session {session_id} switched to {req.channel}", "session": s}

@app.post("/chat", summary="Send message to Master Sales Agent (omnichannel-aware)")
def chat(req: ChatRequest):
    # 1) obtain or create session
    if req.session_id:
        s = load_session_from_db(req.session_id)
        if not s:
            raise HTTPException(status_code=404, detail="Session not found")
        # update channel if different
        if req.channel and req.channel != s.get("channel"):
            s["channel"] = req.channel
    else:
        # create new session
        chan = req.channel or "web"
        if chan not in CHANNELS:
            raise HTTPException(status_code=400, detail=f"Invalid channel. Allowed: {CHANNELS}")
        s = new_session(req.customer_id, chan)

    # 2) store user message into conversation history
    update_session_activity(s, role="user", text=req.message, channel=req.channel or s.get("channel"))

    # 3) naive intent detection/routing (replace with your NLU or intent classifier)
    text = req.message.lower().strip()
    # responses: List[str] = [] # Change to list of dictionaries
    responses: List[Dict[str, Any]] = []

    # greeting
    if any(token in text for token in ["hi","hello","hey","good morning","good evening"]):
        responses.append({"text": "Hello! 👋 I'm your omnichannel shopping assistant. What are you looking for today?"})

    # search / recommendations
    elif any(token in text for token in ["looking for","show me","find","search","i want","want to buy"]):
        recs = recommend_products_stub(s, req.message, topk=4)
        s["context"]["last_recommendations"] = recs
        responses.append({"text": "I found these for you:"})
        for r in recs:
            # Append recommendation as a dictionary
            responses.append({
                "text": f"{r.get('sku', 'N/A')} - {r.get('name', 'N/A')} - Rs.{r.get('price', 'N/A')}",
                "sku": r.get('sku'), # Include SKU for potential future use (e.g., adding to cart)
                "image": r.get("image")
            })
        responses.append({"text": "You can say 'add <SKU>' to add to cart, or ask for more options."})

    # add to cart: "add P001" or "add P001 qty 2"
    elif text.startswith("add "):
        parts = text.split()
        try:
            sku = parts[1].upper()
        except IndexError:
            responses.append({"text": "Please specify the SKU to add, e.g., 'add P001'."})
            update_session_activity(s, role="agent", text=json.dumps(responses), channel=s.get("channel")) # Save responses as JSON string
            return {"session_id": s["session_id"], "responses": responses}

        qty = 1
        if "qty" in parts:
            try:
                qty = int(parts[parts.index("qty")+1])
            except:
                qty = 1
        # check inventory via worker
        inv = check_inventory_stub(sku)
        if inv["total_qty"] <= 0:
            responses.append({"text": f"Sorry, {sku} is out of stock. Would you like alternatives?"})
            # optionally call recommendation worker for alternatives
            alts = recommend_products_stub(s, "similar "+sku, topk=3)
            for a in alts:
                 # Append alternative recommendation as a dictionary
                 responses.append({
                    "text": f"Alt: {a.get('sku', 'N/A')} - {a.get('name', 'N/A')} - Rs.{a.get('price', 'N/A')}",
                    "sku": a.get('sku'),
                    "image": a.get("image")
                })
        else:
            # add to cart in context
            cart = s["context"].setdefault("cart", [])
            cart.append({"sku": sku, "qty": qty})
            responses.append({"text": f"Added {qty} x {sku} to your cart."})
            responses.append({"text": "You can 'show cart' or 'checkout'."})

    # show cart
    elif text in ("show cart","my cart","cart"):
        cart = s["context"].get("cart", [])
        if not cart:
            responses.append({"text": "Your cart is empty."})
        else:
            # summarize cart (you can call pricing/loyalty worker here)
            total = 0
            lines = []
            for line in cart:
                # For demo, map sku->price quickly (replace with product DB lookup)
                price_map = {"P001":2499,"P002":499,"P003":3499,"P004":1999}
                price = price_map.get(line["sku"], 0)
                lines.append(f"{line['qty']} x {line['sku']} -> Rs.{price * line['qty']}")
                total += price * line['qty']
            responses.append({"text": "Cart contents:"})
            for line_text in lines:
                 responses.append({"text": line_text})

            responses.append({"text": f"Total: Rs.{total}"})
            responses.append({"text": "To pay say 'pay by <method>' (card/upi/giftcard)."})
            # store last_total
            s["context"]["last_cart_total"] = total

    # payment intent: 'pay by card'
    elif text.startswith("pay by ") or text.startswith("pay "):
        method = None
        parts = text.split()
        # detect method
        if "by" in parts:
            idx = parts.index("by")
            if idx + 1 < len(parts):
                method = parts[idx+1]
        else:
            # 'pay card' style
            method = parts[1] if len(parts)>1 else "card"
        method = method or "card"
        total = s["context"].get("last_cart_total", 0)
        if total <= 0:
            responses.append({"text": "I don't see anything to pay for. Add items to cart first."})
        else:
            # For demo, assume details supplied in message (not secure) -> in real flows, trigger hosted payment UI
            # Here we simulate a payment worker call
            payment_result = process_payment_stub(amount=total, method=method, details={})
            if payment_result["status"] == "success":
                responses.append({"text": f"Payment successful. TxID: {payment_result['tx_id']}. Order scheduled for fulfillment."})
                # schedule fulfillment (call fulfillment worker)
                order = {
                    "order_id": str(uuid.uuid4())[:8],
                    "status": "confirmed",
                    "channel": s.get("channel"),
                    "items": s["context"].get("cart", []),
                    "total": total,
                    "created_at": datetime.utcnow().isoformat()
                }
                s["context"].setdefault("orders", []).append(order)
                # clear cart
                s["context"]["cart"] = []
                responses.append({"text": f"Order {order['order_id']} created. You will receive updates."})
            else:
                responses.append({"text": "Payment failed: " + payment_result.get("reason","unknown")})
                responses.append({"text": "You can try another payment method."})

    # fallback
    else:
        responses.append({"text": "Sorry, I didn't understand that. You can say 'show me <category>' or 'add <SKU>'."})
        responses.append({"text": "Or say 'help' to see options."})

    # 4) write agent reply into session and persist - Store list of dicts
    update_session_activity(s, role="agent", text=json.dumps(responses), channel=s.get("channel"))

    return {"session_id": s["session_id"], "responses": responses}

# ---------------------------
# Example debug endpoint: list sessions (for dev)
# ---------------------------
@app.get("/sessions", summary="List active session ids (dev)")
def list_sessions():
    conn = sqlite3.connect(DB)
    cur = conn.cursor()
    cur.execute("SELECT session_id, updated_at FROM sessions ORDER BY updated_at DESC LIMIT 50")
    rows = cur.fetchall()
    conn.close()
    return [{"session_id": r[0], "updated_at": r[1]} for r in rows]

