from flask import Flask, request, jsonify
from pyngrok import ngrok
import threading
import requests
import time

# --- 1️⃣ Kill existing ngrok tunnels (prevents 3-tunnel limit error) ---
ngrok.kill()

# --- 2️⃣ Create Flask App ---
app = Flask(__name__)

@app.route("/session", methods=["POST"])
def create_session():
    data = request.get_json()
    return jsonify({"message": "Session created successfully", "data": data})

# --- 3️⃣ Set ngrok auth token ---
