import threading
import uvicorn
from pyngrok import ngrok
import time
import nest_asyncio
import subprocess
import os
import signal


nest_asyncio.apply()  # allows uvicorn to run in Colab

# Function to kill processes running on a specific port
def kill_process_on_port(port):
    try:
        # Find process ID using lsof
        lsof_output = subprocess.check_output(['lsof', '-t', '-i', f':{port}']).decode().strip()
        if lsof_output:
            pids = lsof_output.split('\n')
            for pid in pids:
                try:
                    os.kill(int(pid), signal.SIGKILL)
                    print(f"Killed process {pid} running on port {port}")
                except OSError as e:
                    print(f"Error killing process {pid}: {e}")
    except subprocess.CalledProcessError:
        print(f"No process found running on port {port}")
    except FileNotFoundError:
        print("lsof command not found. Cannot automatically kill processes.")


# Kill any existing processes on port 8000 and ngrok tunnels
kill_process_on_port(8000)
