session_id = '50503ea4' # <-- Replace with your actual session ID


def make_chat_request(session_id_param, message, channel="mobile"):
    """Helper function to make chat requests and handle errors."""
    chat_url = f"{base_url}/chat"
    payload = {
        "session_id": session_id_param,
        "channel": channel,
        "message": message
    }
    print(f"\nSending message: '{message}' to session: {session_id_param}")
    try:
        chat_resp = requests.post(chat_url, json=payload)
        chat_resp.raise_for_status() # Raise an exception for bad status codes (4xx or 5xx)
        print("Chat Response:")
        return chat_resp.json()
    except requests.exceptions.RequestException as e:
        print(f"Error making request to {chat_url}: {e}")
        if hasattr(e, 'response') and e.response is not None:
            print("Response status code:", e.response.status_code)
            print("Response body:", e.response.text)
        return None # Return None if the request failed


