import requests

# Replace with your actual ngrok public URL
# Use the public_url_8000 variable obtained from the cell that starts the FastAPI app and ngrok tunnel (uSFSPITkVLQB)
try:
    from pyngrok.ngrok import NgrokTunnel
    if not isinstance(public_url_8000, NgrokTunnel):
         raise NameError("public_url_8000 is not a valid ngrok tunnel object.")
    base_url = public_url_8000.public_url # Access the URL string
except NameError:
    print("Error: public_url_8000 is not defined. Please run the cell that starts the FastAPI app and ngrok tunnel first.")
    # You might need to manually set the public_url here if the variable is not available
    # base_url = "YOUR_NGROK_PUBLIC_URL_FOR_PORT_8000" # <-- Replace with the actual URL
    raise # Re-raise the error to stop execution if public_url_8000 is not available


# ---------------------------
# 1️⃣ Create a session
# ---------------------------
print(f"Attempting to create session at {base_url}/session")
try:
    session_resp = requests.post(f"{base_url}/session", json={"customer_id":"c1","channel":"mobile"})
    session_resp.raise_for_status() # Raise an exception for bad status codes (4xx or 5xx)
    session_data = session_resp.json()
    session_id = session_data.get("session_id")
    print("Session created! Session ID:", session_id)

    # ---------------------------
    # 2️⃣ Interactive chat loop
    # ---------------------------
    if session_id:
        print("\nStart chatting with the bot! Type 'exit' to quit.\n")

        while True:
            user_msg = input("You: ")
            if user_msg.lower() in ["exit", "quit"]:
                print("Exiting chat. Bye! 👋")
                break

            # Send message to /chat endpoint
            print(f"Sending chat message to {base_url}/chat")
            try:
                chat_resp = requests.post(f"{base_url}/chat", json={
                    "session_id": session_id,
                    "channel": "mobile",
                    "message": user_msg
                })
                chat_resp.raise_for_status() # Raise an exception for bad status codes (4xx or 5xx)
                responses = chat_resp.json().get("responses", [])
                for r in responses:
                    print("Bot:", r)
            except requests.exceptions.RequestException as e:
                print(f"Error sending chat message: {e}")
                if hasattr(e, 'response') and e.response is not None:
                    print("Response status code:", e.response.status_code)
                    print("Response body:", e.response.text)
            except Exception as e:
                print("Error reading bot response:", e)
    else:
        print("Failed to create session, cannot start chat loop.")

except requests.exceptions.RequestException as e:
    print(f"Error creating session: {e}")
    if hasattr(e, 'response') and e.response is not None:
        print("Response status code:", e.response.status_code)
