# recommendation_agent.py
import pandas as pd
from typing import List, Dict

# Load your CSVs (replace with real paths or DB calls)
products_df = pd.read_csv("products.csv")
customers_df = pd.read_csv("customers.csv")

# Mock past purchases (customer_id -> list of SKUs)
past_orders = {
    "c1": ["P002", "P003"],   # Asha bought Tee + Sneakers
    "c2": ["P004"],           # Ravi bought a Dress
    "c3": []                  # Sagar is a new customer
}

def recommend_products(customer_id: str, topk: int = 3) -> List[Dict]:
    """
    Recommend products for a customer.
    If the customer has past orders -> recommend similar category/attributes.
    If new -> recommend trending/popular (here: lowest price for demo).
    """
    if customer_id in past_orders and past_orders[customer_id]:
        bought_skus = past_orders[customer_id]
        bought_products = products_df[products_df["SKU"].isin(bought_skus)]
        categories = bought_products["Category"].unique()

        # Recommend other products in the same category
        candidates = products_df[
            (products_df["Category"].isin(categories)) &
            (~products_df["SKU"].isin(bought_skus))
        ]
        if not candidates.empty:
            # Convert DataFrame rows to dictionaries
            return candidates.sample(min(topk, len(candidates))).to_dict(orient="records")

    # Cold-start: new customer or no past orders → recommend cheapest products
    candidates = products_df.sort_values("Price").head(topk)
    # Convert DataFrame rows to dictionaries
    return candidates.to_dict(orient="records")

# ---------------- Demo ----------------
if __name__ == "__main__":
    print("Recommendations for c1:")
    print(recommend_products("c1"))

    print("\nRecommendations for c2:")
    print(recommend_products("c2"))

    print("\nRecommendations for c3:")
    print(recommend_products("c3"))

