import pandas as pd
import matplotlib.pyplot as plt
import seaborn as sns

# -----------------------------
# Step 1: Recommendations input
# -----------------------------
recommendations = {
    'c1': [{'SKU': 'P005', 'Name': 'Jeans', 'Category': 'Unisex', 'Price': 1800, 'Stock_Online': 6, 'Stock_Store': 4}],
    'c2': [{'SKU': 'P001', 'Name': 'Party Wear Dress', 'Category': 'Women', 'Price': 2500, 'Stock_Online': 5, 'Stock_Store': 2}],
    'c3': [
        {'SKU': 'P002', 'Name': 'Casual Shirt', 'Category': 'Men', 'Price': 1200, 'Stock_Online': 0, 'Stock_Store': 3},
        {'SKU': 'P005', 'Name': 'Jeans', 'Category': 'Unisex', 'Price': 1800, 'Stock_Online': 6, 'Stock_Store': 4},
        {'SKU': 'P001', 'Name': 'Party Wear Dress', 'Category': 'Women', 'Price': 2500, 'Stock_Online': 5, 'Stock_Store': 2}
    ]
}

# -----------------------------
# Step 2: Flatten recommendations into DataFrame
# -----------------------------
rows = []
for customer, recs in recommendations.items():
    for r in recs:
        r_copy = r.copy()
        r_copy['Customer'] = customer
        rows.append(r_copy)

df_recommendations = pd.DataFrame(rows)

# -----------------------------
# Step 3: Filter based on stock
# -----------------------------
df_filtered = df_recommendations[(df_recommendations['Stock_Online'] > 0) | (df_recommendations['Stock_Store'] > 0)]

# -----------------------------
# Step 4: Save to CSV
# -----------------------------
df_filtered.to_csv('customer_recommendations.csv', index=False)
print("Filtered recommendations saved to 'customer_recommendations.csv'.")

# -----------------------------
# Step 5: Personalized messages
# -----------------------------
print("\n--- Personalized Recommendations ---")
for customer in df_filtered['Customer'].unique():
    customer_recs = df_filtered[df_filtered['Customer'] == customer]
    print(f"\nRecommendations for {customer}:")
    for _, item in customer_recs.iterrows():
        print(f"- {item['Name']} ({item['Category']}) - Rs {item['Price']}")

# -----------------------------
# Step 6: Evaluation (optional)
# Requires actual purchase data in df_actual
# -----------------------------
# Example df_actual
df_actual = pd.DataFrame({
    'Customer': ['c1', 'c2', 'c3', 'c3'],
    'SKU': ['P005', 'P001', 'P002', 'P005']
})

# Compute precision
hits = 0
total_recs = 0
for customer in df_filtered['Customer'].unique():
    rec_skus = set(df_filtered[df_filtered['Customer'] == customer]['SKU'])
    actual_skus = set(df_actual[df_actual['Customer'] == customer]['SKU'])
    hits += len(rec_skus & actual_skus)
    total_recs += len(rec_skus)

precision = hits / total_recs if total_recs > 0 else 0
print(f"\nPrecision of recommendations: {precision:.2f}")

# -----------------------------
# Step 7: Analytics & Visualizations
# -----------------------------
# Top recommended items
top_items = df_filtered['Name'].value_counts()
plt.figure(figsize=(6,4))
sns.barplot(x=top_items.index, y=top_items.values, palette="viridis")
plt.title("Top Recommended Items")
plt.ylabel("Count")
plt.xticks(rotation=45)
plt.show()

# Recommendations by category
category_counts = df_filtered['Category'].value_counts()
plt.figure(figsize=(6,4))
sns.barplot(x=category_counts.index, y=category_counts.values, palette="magma")
plt.title("Recommendations by Category")
plt.ylabel("Count")
plt.show()

import pandas as pd
import random

# -----------------------------
# Step 1: Load filtered recommendations
# -----------------------------
# Assuming df_filtered is from previous steps
# Example data if not already defined
df_filtered = pd.DataFrame([
    {'Customer': 'c1', 'SKU': 'P005', 'Name': 'Jeans', 'Category': 'Unisex', 'Price': 1800},
    {'Customer': 'c2', 'SKU': 'P001', 'Name': 'Party Wear Dress', 'Category': 'Women', 'Price': 2500},
    {'Customer': 'c3', 'SKU': 'P002', 'Name': 'Casual Shirt', 'Category': 'Men', 'Price': 1200},
    {'Customer': 'c3', 'SKU': 'P005', 'Name': 'Jeans', 'Category': 'Unisex', 'Price': 1800},
    {'Customer': 'c3', 'SKU': 'P001', 'Name': 'Party Wear Dress', 'Category': 'Women', 'Price': 2500},
])

# -----------------------------
# Step 2: Simulate notifications
# -----------------------------
notifications = {}
for customer in df_filtered['Customer'].unique():
    items = df_filtered[df_filtered['Customer'] == customer]['Name'].tolist()
    notifications[customer] = items
    print(f"Notification sent to {customer}: Recommended items - {', '.join(items)}")

# -----------------------------
# Step 3: Simulate user interactions
# -----------------------------
# Each user randomly clicks/buys some items
interactions = []
for customer, items in notifications.items():
    for item in items:
        clicked = random.choice([0,1])  # 0 = no click, 1 = clicked
        purchased = 1 if clicked and random.random() < 0.5 else 0  # 50% chance to purchase if clicked
        interactions.append({'Customer': customer, 'Item': item, 'Clicked': clicked, 'Purchased': purchased})

df_interactions = pd.DataFrame(interactions)
print("\n--- Simulated User Interactions ---")
print(df_interactions)

# -----------------------------
# Step 4: Track metrics
# -----------------------------
total_recommendations = len(df_interactions)
total_clicks = df_interactions['Clicked'].sum()
total_purchases = df_interactions['Purchased'].sum()

ctr = total_clicks / total_recommendations if total_recommendations > 0 else 0
conversion_rate = total_purchases / total_recommendations if total_recommendations > 0 else 0

print(f"\nClick-Through Rate (CTR): {ctr:.2f}")
print(f"Conversion Rate: {conversion_rate:.2f}")

# -----------------------------
# Step 5: Update recommendations dynamically
# -----------------------------
# Remove items that were purchased from future recommendations
purchased_items = df_interactions[df_interactions['Purchased']==1][['Customer','Item']]
df_updated_recs = df_filtered.copy()

for idx, row in purchased_items.iterrows():
    df_updated_recs = df_updated_recs[~((df_updated_recs['Customer']==row['Customer']) &
                                        (df_updated_recs['Name']==row['Item']))]

print("\n--- Updated Recommendations After Purchases ---")
print(df_updated_recs)

