import streamlit as st
import pandas as pd
import matplotlib.pyplot as plt
import seaborn as sns
import random

st.set_page_config(page_title="Dynamic Recommendation Dashboard", layout="wide")
st.title("Dynamic Retail Recommendation System")

# -----------------------------
# Step 1: Initial recommendation data
# -----------------------------
if 'df_recs' not in st.session_state:
    st.session_state.df_recs = pd.DataFrame([
        {'Customer': 'c1', 'SKU': 'P005', 'Name': 'Jeans', 'Category': 'Unisex', 'Price': 1800},
        {'Customer': 'c2', 'SKU': 'P001', 'Name': 'Party Wear Dress', 'Category': 'Women', 'Price': 2500},
        {'Customer': 'c3', 'SKU': 'P002', 'Name': 'Casual Shirt', 'Category': 'Men', 'Price': 1200},
        {'Customer': 'c3', 'SKU': 'P005', 'Name': 'Jeans', 'Category': 'Unisex', 'Price': 1800},
        {'Customer': 'c3', 'SKU': 'P001', 'Name': 'Party Wear Dress', 'Category': 'Women', 'Price': 2500},
    ])

if 'df_interactions' not in st.session_state:
    st.session_state.df_interactions = pd.DataFrame(columns=['Customer','Item','Clicked','Purchased'])

# -----------------------------
# Step 2: Simulate interactions
# -----------------------------
def simulate_interactions():
    new_interactions = []
    for idx, row in st.session_state.df_recs.iterrows():
        clicked = random.choice([0,1])
        purchased = 1 if clicked and random.random() < 0.5 else 0
        new_interactions.append({'Customer': row['Customer'], 'Item': row['Name'], 'Clicked': clicked, 'Purchased': purchased})

    new_df = pd.DataFrame(new_interactions)
    st.session_state.df_interactions = pd.concat([st.session_state.df_interactions, new_df], ignore_index=True)

    # Remove purchased items from recommendations
    purchased_items = new_df[new_df['Purchased']==1]
    for idx, row in purchased_items.iterrows():
        st.session_state.df_recs = st.session_state.df_recs[~((st.session_state.df_recs['Customer']==row['Customer']) &
                                                            (st.session_state.df_recs['Name']==row['Item']))]

st.button("Simulate Daily Interactions", on_click=simulate_interactions)

# -----------------------------
# Step 3: Metrics
# -----------------------------
total_recommendations = len(st.session_state.df_interactions)
total_clicks = st.session_state.df_interactions['Clicked'].sum()
total_purchases = st.session_state.df_interactions['Purchased'].sum()

ctr = total_clicks / total_recommendations if total_recommendations > 0 else 0
conversion_rate = total_purchases / total_recommendations if total_recommendations > 0 else 0

st.subheader("Key Metrics")
st.metric("Total Recommendations Sent", total_recommendations)
st.metric("Click-Through Rate (CTR)", f"{ctr:.2f}")
st.metric("Conversion Rate", f"{conversion_rate:.2f}")

# -----------------------------
