import streamlit as st
import pandas as pd
import matplotlib.pyplot as plt
import seaborn as sns
import random

st.set_page_config(page_title="Top 5 Recommendation Dashboard", layout="wide")
st.title("Dynamic Retail Recommendation System with Top 5 Recommendations")

# -----------------------------
# Step 1: Initial recommendation data
# -----------------------------
if 'df_recs' not in st.session_state:
    st.session_state.df_recs = pd.DataFrame([
        {'Customer': 'c1', 'SKU': 'P005', 'Name': 'Jeans', 'Category': 'Unisex', 'Price': 1800},
        {'Customer': 'c2', 'SKU': 'P001', 'Name': 'Party Wear Dress', 'Category': 'Women', 'Price': 2500},
        {'Customer': 'c3', 'SKU': 'P002', 'Name': 'Casual Shirt', 'Category': 'Men', 'Price': 1200},
        {'Customer': 'c3', 'SKU': 'P005', 'Name': 'Jeans', 'Category': 'Unisex', 'Price': 1800},
        {'Customer': 'c3', 'SKU': 'P001', 'Name': 'Party Wear Dress', 'Category': 'Women', 'Price': 2500},
    ])

if 'df_interactions' not in st.session_state:
    st.session_state.df_interactions = pd.DataFrame(columns=['Customer','Item','Clicked','Purchased'])

# -----------------------------
# Step 2: Simulate interactions
# -----------------------------
def simulate_interactions():
    new_interactions = []
    for idx, row in st.session_state.df_recs.iterrows():
        clicked = random.choice([0,1])
        purchased = 1 if clicked and random.random() < 0.5 else 0
        new_interactions.append({'Customer': row['Customer'], 'Item': row['Name'], 'Clicked': clicked, 'Purchased': purchased})

    new_df = pd.DataFrame(new_interactions)
    st.session_state.df_interactions = pd.concat([st.session_state.df_interactions, new_df], ignore_index=True)

    # Remove purchased items from recommendations
    purchased_items = new_df[new_df['Purchased']==1]
    for idx, row in purchased_items.iterrows():
        st.session_state.df_recs = st.session_state.df_recs[~((st.session_state.df_recs['Customer']==row['Customer']) &
                                                            (st.session_state.df_recs['Name']==row['Item']))]

st.button("Simulate Daily Interactions", on_click=simulate_interactions)

# -----------------------------
# Step 3: Metrics
# -----------------------------
total_recommendations = len(st.session_state.df_interactions)
total_clicks = st.session_state.df_interactions['Clicked'].sum()
total_purchases = st.session_state.df_interactions['Purchased'].sum()

ctr = total_clicks / total_recommendations if total_recommendations > 0 else 0
conversion_rate = total_purchases / total_recommendations if total_recommendations > 0 else 0

st.subheader("Key Metrics")
st.metric("Total Recommendations Sent", total_recommendations)
st.metric("Click-Through Rate (CTR)", f"{ctr:.2f}")
st.metric("Conversion Rate", f"{conversion_rate:.2f}")

# -----------------------------
# Step 4: Customer Filter
# -----------------------------
customer_list = st.session_state.df_recs['Customer'].unique().tolist()
selected_customer = st.selectbox("Select Customer", customer_list)

st.subheader(f"Current Recommendations for {selected_customer}")
customer_recs = st.session_state.df_recs[st.session_state.df_recs['Customer'] == selected_customer]
st.table(customer_recs[['Name','Category','Price']])

# -----------------------------
# Step 5: Top 5 Recommendations per Customer
# -----------------------------
st.subheader("Top 5 Recommendations per Customer")
top5_table = st.session_state.df_recs.groupby('Customer').apply(lambda x: x.head(5)).reset_index(drop=True)
st.dataframe(top5_table[['Customer','Name','Category','Price']])

# -----------------------------
# Step 6: Top Recommended Items (Seaborn 0.14+ compatible)
# -----------------------------
st.subheader("Top Recommended Items")
top_items_df = st.session_state.df_recs['Name'].value_counts().reset_index()
top_items_df.columns = ['Name','Count']

fig, ax = plt.subplots(figsize=(6,4))
sns.barplot(x='Name', y='Count', data=top_items_df, palette="viridis", ax=ax, hue=None)
if ax.get_legend() is not None:
    ax.get_legend().remove()
ax.set_ylabel("Count")
ax.set_xlabel("Item Name")
ax.set_title("Top Recommended Items")
st.pyplot(fig)

# -----------------------------
# Step 7: Recommendations by Category (Seaborn 0.14+ compatible)
# -----------------------------
st.subheader("Recommendations by Category")
category_counts_df = st.session_state.df_recs['Category'].value_counts().reset_index()
category_counts_df.columns = ['Category','Count']

fig2, ax2 = plt.subplots(figsize=(6,4))
sns.barplot(x='Category', y='Count', data=category_counts_df, palette="magma", ax=ax2, hue=None)
if ax2.get_legend() is not None:
    ax2.get_legend().remove()
ax2.set_ylabel("Count")
ax2.set_xlabel("Category")
ax2.set_title("Recommendations by Category")
st.pyplot(fig2)

# -----------------------------
# Step 8: Interaction Table
# -----------------------------
st.subheader("User Interactions Log")
st.dataframe(st.session_state.df_interactions)

# -----------------------------
# Step 9: Export Data as CSV
# -----------------------------
st.subheader("📥 Export Data")

# Export Recommendations
rec_csv = st.session_state.df_recs.to_csv(index=False).encode('utf-8')
st.download_button(
    label="Download Current Recommendations as CSV",
    data=rec_csv,
    file_name="recommendations.csv",
    mime="text/csv",
)

# Export Interactions
inter_csv = st.session_state.df_interactions.to_csv(index=False).encode('utf-8')
st.download_button(
    label="Download User Interactions Log as CSV",
    data=inter_csv,
    file_name="interactions.csv",
    mime="text/csv",
)

