df_recs = pd.DataFrame([
    {'Customer': 'c1', 'SKU': 'P005', 'Name': 'Jeans', 'Category': 'Unisex', 'Price': 1800},
    {'Customer': 'c2', 'SKU': 'P001', 'Name': 'Party Wear Dress', 'Category': 'Women', 'Price': 2500},
    {'Customer': 'c3', 'SKU': 'P002', 'Name': 'Casual Shirt', 'Category': 'Men', 'Price': 1200},
    {'Customer': 'c3', 'SKU': 'P005', 'Name': 'Jeans', 'Category': 'Unisex', 'Price': 1800},
    {'Customer': 'c3', 'SKU': 'P001', 'Name': 'Party Wear Dress', 'Category': 'Women', 'Price': 2500},
])
print("📌 Original Recommendations")
display(df_recs)

# -----------------------------
# Step 2: Sorting & Filtering Functions
# -----------------------------
def filter_and_sort(df, category="All", sort_by="Default"):
    filtered = df.copy()
    if category != "All":
        filtered = filtered[filtered['Category'] == category]

    if sort_by == "Price: Low to High":
        filtered = filtered.sort_values(by="Price", ascending=True)
    elif sort_by == "Price: High to Low":
        filtered = filtered.sort_values(by="Price", ascending=False)
    elif sort_by == "Popularity":
        pop_counts = filtered['Name'].value_counts()
        filtered['Popularity'] = filtered['Name'].map(pop_counts)
        filtered = filtered.sort_values(by="Popularity", ascending=False)

    return filtered

def customer_recommendations(df, customer_id, category="All", sort_by="Default"):
    customer_df = df[df['Customer'] == customer_id]
    return filter_and_sort(customer_df, category=category, sort_by=sort_by)

# -----------------------------
# Step 3: Simulate Interactions
# -----------------------------
np.random.seed(42)
df_interactions = df_recs.copy()
df_interactions['Clicked'] = np.random.choice([0,1], size=len(df_interactions))
df_interactions['Purchased'] = df_interactions['Clicked'] * np.random.choice([0,1], size=len(df_interactions))
df_interactions['Timestamp'] = pd.date_range(start='2025-09-01', periods=len(df_interactions), freq='D')
df_interactions['Date'] = df_interactions['Timestamp'].dt.date
print("📌 Simulated Interactions")
display(df_interactions)

# -----------------------------
# Step 4: Metrics Evaluation
# -----------------------------
ground_truth = {
    "c1": {"P005"},
    "c2": {"P001"},
    "c3": {"P002", "P005"}
}

def precision_at_k(recs, truth, k=3):
    rec_items = recs['SKU'].head(k).tolist()
    relevant = truth.intersection(rec_items)
    return len(relevant) / k if k > 0 else 0

def recall_at_k(recs, truth, k=3):
    rec_items = recs['SKU'].head(k).tolist()
    relevant = truth.intersection(rec_items)
    return len(relevant) / len(truth) if len(truth) > 0 else 0

def coverage(df, all_items):
    recommended_items = set(df['SKU'].unique())
    return len(recommended_items) / len(all_items)

precisions, recalls, customers = [], [], []
for cust, truth_items in ground_truth.items():
    recs = customer_recommendations(df_recs, cust)
    prec = precision_at_k(recs, truth_items, k=3)
    rec = recall_at_k(recs, truth_items, k=3)
    precisions.append(prec)
    recalls.append(rec)
    customers.append(cust)
    print(f"Customer {cust}: Precision@3 = {prec:.2f}, Recall@3 = {rec:.2f}")

all_items = set(df_recs['SKU'].unique())
cov = coverage(df_recs, all_items)
print(f"\nOverall Catalog Coverage = {cov:.2%}")

# -----------------------------
# Step 5: Visualizations
# -----------------------------
# Top Recommended Items
top_items_df = df_recs['Name'].value_counts().reset_index()
top_items_df.columns = ['Name','Count']

plt.figure(figsize=(6,4))
sns.barplot(x='Name', y='Count', data=top_items_df, color="skyblue")
plt.title("Top Recommended Items")
plt.show()

# Recommendations by Category
category_counts_df = df_recs['Category'].value_counts().reset_index()
category_counts_df.columns = ['Category','Count']

plt.figure(figsize=(6,4))
sns.barplot(x='Category', y='Count', data=category_counts_df, color="orange")
plt.title("Recommendations by Category")
plt.show()

# Precision / Recall per Customer
plt.figure(figsize=(6,4))
plt.bar(customers, precisions, label="Precision@3")
plt.bar(customers, recalls, alpha=0.5, label="Recall@3")
plt.title("Precision and Recall per Customer")
plt.ylabel("Metric Value")
plt.legend()
plt.show()

# Coverage Pie Chart
plt.figure(figsize=(5,5))
plt.pie([cov, 1-cov], labels=["Covered", "Not Covered"], autopct="%.1f%%", startangle=90)
plt.title("Catalog Coverage")
plt.show()

# -----------------------------
# Step 6: Trend Analysis
# -----------------------------
daily_metrics = df_interactions.groupby('Date').agg(
    Total_Recommendations=('Name', 'count'),
    Clicks=('Clicked', 'sum'),
    Purchases=('Purchased', 'sum')
).reset_index()

plt.figure(figsize=(8,4))
plt.plot(daily_metrics['Date'], daily_metrics['Total_Recommendations'], marker='o', label="Recommendations")
plt.plot(daily_metrics['Date'], daily_metrics['Clicks'], marker='o', label="Clicks")
plt.plot(daily_metrics['Date'], daily_metrics['Purchases'], marker='o', label="Purchases")
plt.xticks(rotation=45)
plt.title("Daily Recommendation Trends")
plt.xlabel("Date")
plt.ylabel("Count")
plt.legend()
plt.tight_layout()
plt.show()

# -----------------------------
# Step 7: Export Data as CSV
# -----------------------------
df_recs.to_csv("recommendations.csv", index=False)
df_interactions.to_csv("interactions.csv", index=False)
print("✅ Recommendations and interactions saved as CSV files.")

# -----------------------------
# Step 8: Interactive Widgets for Customer Exploration
# -----------------------------
customer_dropdown = widgets.Dropdown(
    options=df_recs['Customer'].unique().tolist(),
    description='Customer:'
)
category_dropdown = widgets.Dropdown(
    options=['All'] + df_recs['Category'].unique().tolist(),
    description='Category:'
)
sort_dropdown = widgets.Dropdown(
    options=["Default", "Price: Low to High", "Price: High to Low", "Popularity"],
    description='Sort by:'
)
button = widgets.Button(description="Show Recommendations")
out = widgets.Output()

def show_recs(b):
    out.clear_output()
    cust = customer_dropdown.value
    cat = category_dropdown.value
    sort_by = sort_dropdown.value
    filtered = customer_recommendations(df_recs, cust, category=cat, sort_by=sort_by)
    with out:
        print(f"Recommendations for Customer {cust} (Category={cat}, Sort={sort_by}):")
        display(filtered[['Customer','Name','Category','Price']])

button.on_click(show_recs)
display(customer_dropdown, category_dropdown, sort_dropdown, button, out)

