    # Ensure string type and strip spaces
    df['Customer'] = df['Customer'].astype(str).str.strip()
    customer_id = str(customer_id).strip()

    # Filter customer
    customer_df = df[df['Customer'] == customer_id]

    if customer_df.empty:
        print(f"No data found for Customer '{customer_id}'")
        return pd.DataFrame(columns=['Name','Count'])

    # Count top-K items
    top_items = customer_df['Name'].value_counts().head(top_k)
    return top_items.reset_index().rename(columns={'index':'Name','Name':'Count'})

