# recommendation_agent.py
"""
Recommendation Agent (hybrid demo)

Endpoints:
- POST /seed-demo             -> seed demo SKUs and customers (from your images)
- GET  /recommend/{customer_id}?n=5&filter_available=true
                                -> top-n recommendations for a customer
- GET  /recommend-similar/{sku}?n=5
                                -> items similar to a given SKU
- GET  /popular?n=5            -> global popular items

Optional integration:
- If inventory agent is running, pass ?inventory_url=http://127.0.0.1:8000
  to filter only items currently available (online or at stores) by calling
  its /availability/{sku} endpoint.
"""

from fastapi import FastAPI, HTTPException, Query
from pydantic import BaseModel
from typing import List, Optional, Dict, Tuple
from sqlalchemy import create_engine, Column, Integer, String, Text, ForeignKey, func
from sqlalchemy.orm import sessionmaker, declarative_base, relationship, scoped_session
import uuid
import requests
import math

# ----------------------------
# DB / ORM (SQLite simple demo)
# ----------------------------
DATABASE_URL = "sqlite:///./recommendation.db"
engine = create_engine(DATABASE_URL, connect_args={"check_same_thread": False})
SessionLocal = scoped_session(sessionmaker(bind=engine, expire_on_commit=False))
Base = declarative_base()

class SKU(Base):
    __tablename__ = "skus"
    id = Column(Integer, primary_key=True)
    sku_code = Column(String, unique=True, index=True)
    name = Column(String)
    category = Column(String)
    price = Column(Integer)
    # popularity field (e.g., historical sales)
    sales_count = Column(Integer, default=0)
    # free text tags (history-like)
    tags = Column(Text, default="")

class Customer(Base):
    __tablename__ = "customers"
    id = Column(Integer, primary_key=True)
    customer_code = Column(String, unique=True, index=True)
    name = Column(String)
    loyalty = Column(String)  # Bronze / Silver / Gold
    points = Column(Integer, default=0)
    history_raw = Column(Text, default="")  # comma-separated purchased items (by name or keywords)

class PurchaseHistory(Base):
    __tablename__ = "purchases"
    id = Column(Integer, primary_key=True)
    customer_id = Column(Integer, ForeignKey("customers.id"))
    sku_id = Column(Integer, ForeignKey("skus.id"))

    customer = relationship("Customer")
    sku = relationship("SKU")

Base.metadata.create_all(bind=engine)

# ----------------------------
# FastAPI app
# ----------------------------
app = FastAPI(title="Recommendation Agent (demo)")

# ----------------------------
# Helper utilities
# ----------------------------
def get_session():
    return SessionLocal()

def tokenize(text: Optional[str]) -> List[str]:
    if not text:
        return []
    return [t.strip().lower() for t in text.split(",") if t.strip()]

def jaccard(a: set, b: set) -> float:
    if not a and not b:
        return 0.0
    inter = len(a & b)
    union = len(a | b)
    return inter / union if union else 0.0

def cosine_sim(vec1: Dict[str, float], vec2: Dict[str, float]) -> float:
    # simple cosine: dot / (||a|| * ||b||)
    keys = set(vec1.keys()) | set(vec2.keys())
    dot = sum(vec1.get(k, 0.0) * vec2.get(k, 0.0) for k in keys)
    norm1 = math.sqrt(sum(v * v for v in vec1.values()))
    norm2 = math.sqrt(sum(v * v for v in vec2.values()))
    if norm1 == 0 or norm2 == 0:
        return 0.0
    return dot / (norm1 * norm2)

def sku_to_profile(sku: SKU) -> Dict[str, float]:
    # convert SKU attributes (category, tags, name tokens) to a simple term-frequency dict
    tf = {}
    for token in [sku.category] + tokenize(sku.tags) + tokenize(sku.name):
        if not token:
            continue
        tf[token] = tf.get(token, 0) + 1.0
    return tf

def customer_profile(session, customer: Customer) -> Dict[str, float]:
    # build profile from customer's history (sku categories & tags) and loyalty weight
    profile = {}
    # history SKUs
    purchases = session.query(PurchaseHistory).filter(PurchaseHistory.customer_id == customer.id).all()
    for p in purchases:
        if p.sku:
            sku_prof = sku_to_profile(p.sku)
            for k, v in sku_prof.items():
                profile[k] = profile.get(k, 0.0) + v
    # also consider raw history names
    for token in tokenize(customer.history_raw):
        profile[token] = profile.get(token, 0.0) + 0.5
    # boost by loyalty tier a little
    loyalty_boosts = {"bronze": 0.0, "silver": 0.2, "gold": 0.5}
    boost = loyalty_boosts.get((customer.loyalty or "").lower(), 0.0)
    if boost:
        for k in list(profile.keys()):
            profile[k] = profile[k] * (1.0 + boost)
    return profile

def fetch_inventory_availability(inventory_url: str, sku_code: str) -> bool:
    # returns True if SKU has >0 availability online or in any store
    try:
        resp = requests.get(f"{inventory_url.rstrip('/')}/availability/{sku_code}", timeout=2)
        if resp.status_code != 200:
            return True  # be permissive if inventory is unreachable
        data = resp.json()
        if data.get("available_online", 0) > 0:
            return True
        stores = data.get("stores", [])
        for s in stores:
            if s.get("available_qty", 0) > 0:
                return True
        return False
    except Exception:
        # conservative: if inventory agent can't be reached, allow item (preference to not block)
        return True

# ----------------------------
# Seeding endpoint for demo
# ----------------------------
@app.post("/seed-demo")
def seed_demo():
    """
    Seed SKUs and Customers from the images you provided.
    SKUs: P001..P005, Customers: C001..C005
    """
    session = get_session()
    try:
        # clear tables
        session.query(PurchaseHistory).delete()
        session.query(Customer).delete()
        session.query(SKU).delete()
        session.commit()

        # seed SKUs (from your SKU table image)
        sku_data = [
            {"sku_code":"P001","name":"Party Wear","category":"Women","price":2500,"sales_count":50,"tags":"party,evening"},
            {"sku_code":"P002","name":"Casual Shirt","category":"Men","price":1200,"sales_count":30,"tags":"casual,shirt"},
            {"sku_code":"P003","name":"Sneakers","category":"Unisex","price":2800,"sales_count":80,"tags":"shoes,sneakers"},
            {"sku_code":"P004","name":"Saree","category":"Women","price":3500,"sales_count":40,"tags":"traditional,saree"},
            {"sku_code":"P005","name":"Jeans","category":"Unisex","price":1800,"sales_count":70,"tags":"denim,jeans"},
        ]
        sku_objs = {}
        for s in sku_data:
            sk = SKU(sku_code=s["sku_code"], name=s["name"], category=s["category"], price=s["price"], sales_count=s["sales_count"], tags=s.get("tags",""))
            session.add(sk)
            session.flush()
            sku_objs[s["sku_code"]] = sk

        # seed customers (from your customer table image)
        cust_data = [
            {"customer_code":"C001","name":"Aditi","loyalty":"Gold","points":200,"history":"Kurta,Jeans"},
            {"customer_code":"C002","name":"Rahul","loyalty":"Silver","points":80,"history":"Shirt,Sneakers"},
            {"customer_code":"C003","name":"Meera","loyalty":"Gold","points":300,"history":"Saree,Heels"},
            {"customer_code":"C004","name":"Arjun","loyalty":"Bronze","points":40,"history":"Tshirt,Shorts"},
            {"customer_code":"C005","name":"Neha","loyalty":"Silver","points":120,"history":"Dress,Handbag"},
        ]
        cust_objs = {}
        for c in cust_data:
            cu = Customer(customer_code=c["customer_code"], name=c["name"], loyalty=c["loyalty"], points=c["points"], history_raw=c["history"])
            session.add(cu)
            session.flush()
            cust_objs[c["customer_code"]] = cu

        # create some purchase history links (toy examples mapping to SKUs)
        # Map tokens in history to skus where obvious
        mapping = {
            "jeans":"P005",
            "sneakers":"P003",
            "saree":"P004",
            "shirt":"P002",
            "kurta": "P004"  # approximate
        }
        for cust in cust_objs.values():
            for token in tokenize(cust.history_raw):
                sku_code = mapping.get(token.lower())
                if sku_code:
                    ph = PurchaseHistory(customer_id=cust.id, sku_id=sku_objs[sku_code].id)
                    session.add(ph)

        session.commit()
        return {"status":"seeded", "skus": len(sku_data), "customers": len(cust_data)}
    finally:
        session.close()

# ----------------------------
# Recommendation logic
# ----------------------------
def recommend_for_customer(customer_id: str, n: int = 5, inventory_url: Optional[str]=None) -> List[Dict]:
    session = get_session()
    try:
        cust = session.query(Customer).filter(Customer.customer_code == customer_id).first()
        if not cust:
            raise HTTPException(status_code=404, detail="Customer not found")

        # prepare candidate SKUs
        all_skus = session.query(SKU).all()
        sku_profiles = {sku.sku_code: sku_to_profile(sku) for sku in all_skus}
        cust_profile = customer_profile(session, cust)

        # 1) content score: cosine between customer profile and sku profile
        content_scores = {}
        for sku in all_skus:
            content_scores[sku.sku_code] = cosine_sim(cust_profile, sku_profiles[sku.sku_code])

        # 2) collaborative score: find other customers with overlapping SKUs and borrow their SKUs
        # (simple overlap: Jaccard between sets of sku_codes)
        cust_ph = session.query(PurchaseHistory).filter(PurchaseHistory.customer_id == cust.id).all()
        cust_skus = set([ph.sku.sku_code for ph in cust_ph if ph.sku])
        collab_scores = {sku.sku_code: 0.0 for sku in all_skus}
        if cust_skus:
            # compute similarity to other customers
            other_customers = session.query(Customer).all()
            for other in other_customers:
                if other.customer_code == cust.customer_code:
                    continue
                other_ph = session.query(PurchaseHistory).filter(PurchaseHistory.customer_id == other.id).all()
                other_skus = set([oph.sku.sku_code for oph in other_ph if oph.sku])
                sim = jaccard(cust_skus, other_skus)
                if sim <= 0:
                    continue
                # boost items the other customer has (not in current cust)
                for s in other_skus - cust_skus:
                    collab_scores[s] = max(collab_scores.get(s, 0.0), sim)

        # 3) popularity score: normalized sales_count
        max_sales = max((sku.sales_count or 0) for sku in all_skus) or 1
        popularity = {sku.sku_code: (sku.sales_count or 0) / max_sales for sku in all_skus}

        # 4) final hybrid score (weights)
        # Weights: content 0.5, collaborative 0.25, popularity 0.25, with loyalty boost
        final_scores = {}
        loyalty_boost = {"bronze": 0.0, "silver": 0.05, "gold": 0.1}
        boost = loyalty_boost.get((cust.loyalty or "").lower(), 0.0)

        for sku in all_skus:
            s = sku.sku_code
            score = 0.5 * content_scores.get(s, 0.0) + 0.25 * collab_scores.get(s, 0.0) + 0.25 * popularity.get(s, 0.0)
            # small price sensitivity: cheap items slightly prefered for low-points customers (optional)
            if cust.points < 100 and sku.price and sku.price < 2000:
                score += 0.02
            # apply loyalty multiplier
            score = score * (1.0 + boost)
            final_scores[s] = score

        # remove items customer already purchased (optional)
        candidate_scores = {s: sc for s, sc in final_scores.items() if s not in cust_skus}

        # optionally filter by inventory availability
        if inventory_url:
            filtered = {}
            for s, sc in candidate_scores.items():
                if fetch_inventory_availability(inventory_url, s):
                    filtered[s] = sc
            candidate_scores = filtered

        # sort and return top-n with metadata
        ranked = sorted(candidate_scores.items(), key=lambda x: x[1], reverse=True)[:n]
        result = []
        for sku_code, score in ranked:
            sku = session.query(SKU).filter(SKU.sku_code == sku_code).first()
            result.append({
                "sku": sku_code,
                "name": sku.name,
                "category": sku.category,
                "price": sku.price,
                "score": round(score, 4)
            })
        return result
    finally:
        session.close()

def similar_items(sku_code: str, n: int = 5) -> List[Dict]:
    session = get_session()
    try:
        target = session.query(SKU).filter(SKU.sku_code == sku_code).first()
        if not target:
            raise HTTPException(status_code=404, detail="SKU not found")
        all_skus = session.query(SKU).filter(SKU.sku_code != sku_code).all()
        target_profile = sku_to_profile(target)
        sims = []
        for s in all_skus:
            sim = cosine_sim(target_profile, sku_to_profile(s))
            sims.append((s, sim))
        sims = sorted(sims, key=lambda x: x[1], reverse=True)[:n]
        return [{"sku": s.sku_code, "name": s.name, "category": s.category, "price": s.price, "sim": round(sim,4)} for s, sim in sims]
    finally:
        session.close()

# ----------------------------
# API Endpoints
# ----------------------------
@app.get("/recommend/{customer_id}")
def recommend_endpoint(customer_id: str,
                       n: int = Query(5, ge=1, le=20),
                       inventory_url: Optional[str] = Query(None, description="optional Inventory Agent base URL to filter availability")):
    """
    Return top-n recommendations for a customer. Optionally pass inventory_url=http://127.0.0.1:8000
    to filter only items that inventory reports as available.
    """
    recs = recommend_for_customer(customer_id, n=n, inventory_url=inventory_url)
    return {"customer": customer_id, "recommendations": recs}

@app.get("/recommend-similar/{sku_code}")
def recommend_similar_endpoint(sku_code: str, n: int = Query(5, ge=1, le=20)):
    sims = similar_items(sku_code, n=n)
    return {"sku": sku_code, "similar": sims}

@app.get("/popular")
def popular_endpoint(n: int = Query(5, ge=1, le=20)):
    session = get_session()
    try:
        skus = session.query(SKU).order_by(SKU.sales_count.desc()).limit(n).all()
        return {"popular": [{"sku": s.sku_code, "name": s.name, "sales_count": s.sales_count} for s in skus]}
    finally:
        session.close()

class PurchaseHistory(Base):
    __tablename__ = "purchases"
    id = Column(Integer, primary_key=True)
    customer_id = Column(Integer, ForeignKey("customers.id"))
    sku_id = Column(Integer, ForeignKey("skus.id"))

    customer = relationship("Customer")
    sku = relationship("SKU")

Base.metadata.create_all(bind=engine)

# ----------------------------
# FastAPI app
# ----------------------------
app = FastAPI(title="Recommendation Agent (demo)")

# ----------------------------
# Helper utilities
# ----------------------------
def get_session():
    return SessionLocal()

def tokenize(text: Optional[str]) -> List[str]:
    if not text:
        return []
    return [t.strip().lower() for t in text.split(",") if t.strip()]

def jaccard(a: set, b: set) -> float:
    if not a and not b:
        return 0.0
    inter = len(a & b)
    union = len(a | b)
    return inter / union if union else 0.0

def cosine_sim(vec1: Dict[str, float], vec2: Dict[str, float]) -> float:
    # simple cosine: dot / (||a|| * ||b||)
    keys = set(vec1.keys()) | set(vec2.keys())
    dot = sum(vec1.get(k, 0.0) * vec2.get(k, 0.0) for k in keys)
    norm1 = math.sqrt(sum(v * v for v in vec1.values()))
    norm2 = math.sqrt(sum(v * v for v in vec2.values()))
    if norm1 == 0 or norm2 == 0:
        return 0.0
    return dot / (norm1 * norm2)

def sku_to_profile(sku: SKU) -> Dict[str, float]:
    # convert SKU attributes (category, tags, name tokens) to a simple term-frequency dict
    tf = {}
    for token in [sku.category] + tokenize(sku.tags) + tokenize(sku.name):
        if not token:
            continue
        tf[token] = tf.get(token, 0) + 1.0
    return tf

def customer_profile(session, customer: Customer) -> Dict[str, float]:
    # build profile from customer's history (sku categories & tags) and loyalty weight
    profile = {}
    # history SKUs
    purchases = session.query(PurchaseHistory).filter(PurchaseHistory.customer_id == customer.id).all()
    for p in purchases:
        if p.sku:
            sku_prof = sku_to_profile(p.sku)
            for k, v in sku_prof.items():
                profile[k] = profile.get(k, 0.0) + v
    # also consider raw history names
    for token in tokenize(customer.history_raw):
        profile[token] = profile.get(token, 0.0) + 0.5
    # boost by loyalty tier a little
    loyalty_boosts = {"bronze": 0.0, "silver": 0.2, "gold": 0.5}
    boost = loyalty_boosts.get((customer.loyalty or "").lower(), 0.0)
    if boost:
        for k in list(profile.keys()):
            profile[k] = profile[k] * (1.0 + boost)
    return profile

def fetch_inventory_availability(inventory_url: str, sku_code: str) -> bool:
    # returns True if SKU has >0 availability online or in any store
    try:
        resp = requests.get(f"{inventory_url.rstrip('/')}/availability/{sku_code}", timeout=2)
        if resp.status_code != 200:
            return True  # be permissive if inventory is unreachable
        data = resp.json()
        if data.get("available_online", 0) > 0:
            return True
        stores = data.get("stores", [])
        for s in stores:
            if s.get("available_qty", 0) > 0:
                return True
        return False
    except Exception:
        # conservative: if inventory agent can't be reached, allow item (preference to not block)
        return True

