import pandas as pd

# Load data
customers_df = pd.read_csv("customers.csv")
products_df = pd.read_csv("products.csv")

def recommendation_agent(customer_id, top_k=3):
    """
    Recommend top-k products for a customer based on purchase history
    and stock availability.
    """
    # Get the customer row
    customer = customers_df[customers_df['CustomerID'] == customer_id]
    if customer.empty:
        return pd.DataFrame()  # No such customer

    # Get customer's past purchases
    history = customer['History'].values[0].split(",")

    # Exclude items already purchased
    candidate_products = products_df[~products_df['Name'].isin(history)]

    # Identify preferred categories based on history
    preferred_categories = []
    for item in history:
        match = products_df[products_df['Name'].str.contains(item, case=False, na=False)]
        if not match.empty:
            preferred_categories.extend(match['Category'].tolist())

    # Filter candidates: same category OR unisex
    if preferred_categories:
        candidate_products = candidate_products[
            (candidate_products['Category'].isin(preferred_categories)) |
            (candidate_products['Category'] == "Unisex")
        ]

    # Only keep items in stock
    candidate_products = candidate_products[
        (candidate_products['Stock_Online'] > 0) | (candidate_products['Stock_Store'] > 0)
    ]

    # Sort: prioritize stock first, then lower price
    recs = candidate_products.sort_values(
        by=["Stock_Online", "Stock_Store", "Price"], ascending=[False, False, True]
    ).head(top_k)

    return recs[["SKU", "Name", "Category", "Price", "Stock_Online", "Stock_Store"]]

def recommendation_agent(customer_id, top_k=3):
    """Recommend top-k products for a customer based on purchase history
    and stock availability, with debug prints."""

    # Get the customer row
    customer = customers_df[customers_df['CustomerID'] == customer_id]
    if customer.empty:
        print("❌ Customer not found:", customer_id)
