import pandas as pd
import smtplib
from email.mime.multipart import MIMEMultipart
from email.mime.text import MIMEText
import schedule
import time

# -----------------------------
# Step 0: Sample Data
# -----------------------------
customers_df = pd.DataFrame({
    'CustomerID': ['C001', 'C002'],
    'Name': ['Aditi', 'Rahul'],
    'History': ['Kurta,Jeans', 'Shirt,Sneakers'],
    'Email': ['customer1@gmail.com', 'customer2@gmail.com']  # replace with real emails
})

products_df = pd.DataFrame({
    'SKU': ['P001','P002','P003','P004','P005'],
    'Name': ['Party Wear Dress','Shirt','Sneakers','Kurta','Jeans'],
    'Category': ['Women','Men','Unisex','Women','Unisex'],
    'Price': [2500,1200,3000,1800,1800],
    'Stock_Online':[5,2,3,6,4],
    'Stock_Store':[2,5,1,2,4]
})

# -----------------------------
# Step 1: Recommendation Function
# -----------------------------
def recommendation_agent(customer_id, top_k=3):
    customer = customers_df[customers_df['CustomerID'] == customer_id]
    if customer.empty:
        return pd.DataFrame()

    history = customer['History'].values[0].split(",")
    candidate_products = products_df[~products_df['Name'].isin(history)]

    preferred_categories = []
    for item in history:
        match = products_df[products_df['Name'].str.contains(item, case=False, na=False)]
        if not match.empty:
            preferred_categories.extend(match['Category'].tolist())

    if preferred_categories:
        candidate_products = candidate_products[
            (candidate_products['Category'].isin(preferred_categories)) |
            (candidate_products['Category'] == "Unisex")
        ]

    candidate_products = candidate_products[
        (candidate_products['Stock_Online'] > 0) | (candidate_products['Stock_Store'] > 0)
    ]

    recs = candidate_products.sort_values(
        by=["Stock_Online", "Stock_Store", "Price"], ascending=[False, False, True]
    ).head(top_k)

    return recs[["SKU", "Name", "Category", "Price", "Stock_Online", "Stock_Store"]]

# -----------------------------
# Step 2: Generate Recommendations for All Customers
# -----------------------------
all_recs = {}
for cid in customers_df['CustomerID']:
    all_recs[cid] = recommendation_agent(cid)

final_recs = pd.concat(all_recs.values(), keys=all_recs.keys(), names=['CustomerID'])

# -----------------------------
# Step 3: Low-stock Notifications
# -----------------------------
low_stock_recs = final_recs[
    (final_recs['Stock_Online'] <= 5) | (final_recs['Stock_Store'] <= 5)
]

notifications = {}
for cid in customers_df['CustomerID']:
    customer_items = low_stock_recs.loc[cid] if cid in low_stock_recs.index else pd.DataFrame()
    if not customer_items.empty:
        notifications[cid] = list(customer_items['Name'])

# -----------------------------
# Step 4: Email Function
# -----------------------------
EMAIL_ADDRESS = "your_email@gmail.com"  # replace
EMAIL_PASSWORD = "your_app_password"    # replace

def send_email(to_email, subject, body):
    msg = MIMEMultipart()
    msg['From'] = EMAIL_ADDRESS
    msg['To'] = to_email
    msg['Subject'] = subject
    msg.attach(MIMEText(body, 'plain'))
    try:
        server = smtplib.SMTP('smtp.gmail.com', 587)
        server.starttls()
        server.login(EMAIL_ADDRESS, EMAIL_PASSWORD)
        server.send_message(msg)
        server.quit()
        print(f"✅ Email sent to {to_email}")
    except Exception as e:
        print(f"❌ Failed to send email to {to_email}: {e}")

# -----------------------------
# Step 5: Daily Notification Job
# -----------------------------
def daily_notification_job():
    print("📢 Running daily notifications...")
    for cid, items in notifications.items():
        customer_email = customers_df.loc[customers_df['CustomerID'] == cid, 'Email'].values[0]
        customer_name = customers_df.loc[customers_df['CustomerID'] == cid, 'Name'].values[0]

        subject = "Your Daily Product Recommendations!"
        body = f"Hello {customer_name},\n\nThe following products you might like are running low on stock:\n"
        for item in items:
            body += f" - {item}\n"
        body += "\nGrab them before they are gone!\n\nBest regards,\nRetail Team"

        send_email(customer_email, subject, body)

# -----------------------------
# Step 6: Schedule Daily Email
# -----------------------------
# Example: run every day at 10:00 AM
schedule.every().day.at("10:00").do(daily_notification_job)

print("⏰ Scheduler started. Waiting for daily notification time...")

while True:
    schedule.run_pending()
    time.sleep(60)  # check every minute

