# -----------------------------
# Step 1: Analytics Agent (Defining analytics_agent here for independence)
# -----------------------------
# Assuming analytics_agent is defined in a previous cell.
# If not available, this part will not function as expected.
# For this cell to run independently, I'll include the definition:
def analytics_agent():
    report = {}

    # 1. Top-selling products (based on frequency in history)
    all_history = []
    for h in customers_df['History']:
        if isinstance(h, str):
            all_history.extend(h.split(","))
        elif isinstance(h, list):
            all_history.extend(h)

    if all_history:
        top_selling = pd.Series(all_history).value_counts().head(5).to_dict()
