import random

# -----------------------------
# Step 1: Function to simulate stock updates
# -----------------------------
def simulate_stock_change(min_stock=0, max_stock=10, interval=10):
    """
    Randomly updates product stock every `interval` seconds.
    """
    def stock_loop():
        while True:
            # Randomly change stock for each product
            for idx in products_df.index:
                products_df.at[idx, 'Stock_Online'] = random.randint(min_stock, max_stock)
                products_df.at[idx, 'Stock_Store'] = random.randint(min_stock, max_stock)
            print(f"🔄 Stock updated! (Online + Store)")
            time.sleep(interval)

    thread = threading.Thread(target=stock_loop)
    thread.daemon = True
    thread.start()
    print(f"⏱ Stock simulation running every {interval} seconds...")

# -----------------------------
# Step 2: Start stock simulation
# -----------------------------
simulate_stock_change(min_stock=0, max_stock=10, interval=10)

# -----------------------------
# Step 1: Function to highlight low-stock
# -----------------------------
def highlight_low_stock(recs_df):
    """
    Adds visual highlighting for low-stock products.
    Stock threshold: total stock <= 3
    """
    def highlight(row):
        total_stock = row['Stock_Online'] + row['Stock_Store']
        if total_stock <= 3:
            return ['background-color: tomato']*len(row)
        else:
            return ['']*len(row)
    return recs_df.style.apply(highlight, axis=1)

