# Step 2: Update recommendation_agent display
# -----------------------------
def show_recommendations_highlight(b):
    with out_main:
        clear_output(wait=True)
        cid = customer_dropdown.value
        recs = recommendation_agent(cid)
        print(f"🎯 Recommendations for {cid} (low-stock highlighted in red):")
        display(highlight_low_stock(recs))

# Link button
btn_show_recs.on_click(show_recommendations_highlight)

