    critical_items = products_df[
        (products_df['Stock_Online'] + products_df['Stock_Store']) <= 1
    ]
    if not critical_items.empty:
        print("⚠️ CRITICAL LOW STOCK ALERT! ⚠️")
        for _, row in critical_items.iterrows():
            total_stock = row['Stock_Online'] + row['Stock_Store']
            print(f"- {row['Name']} (Total Stock: {total_stock})")
    else:
        print("✅ No critical low-stock items.")

