# -----------------------------
# Function: Customer-specific low-stock alert
# -----------------------------
def show_customer_low_stock_alert(customer_id):
    customer = customers_df[customers_df['CustomerID'] == customer_id]
    if customer.empty:
        print("❌ Customer not found")
        return

    history = customer['History'].values[0].split(",")
    low_stock_items = []

    for item in history:
        row = products_df[products_df['Name'].str.contains(item, case=False, na=False)]
        if not row.empty:
            total_stock = row['Stock_Online'].values[0] + row['Stock_Store'].values[0]
            if total_stock <= 3:  # low-stock threshold
                low_stock_items.append((row['Name'].values[0], total_stock))

    if low_stock_items:
        print("⚠️ Customer-Specific Low Stock Alert! ⚠️")
        for name, stock in low_stock_items:
            print(f"- {name} (Total Stock: {stock})")
    else:
        print("✅ No low-stock items for this customer.")

