if 'sales_log' not in globals():
    sales_log = pd.DataFrame(columns=['Timestamp', 'CustomerID', 'Product', 'Quantity'])

# -----------------------------
# Step 2: Update automated sales simulation to log sales
# -----------------------------
def automated_sales_simulation_with_log(interval=15, max_quantity=3):
    """
    Simulate random sales every `interval` seconds and log them.
    """
    def simulation_loop():
        global sales_log
        while True:
            customer_id = random.choice(customers_df['CustomerID'].tolist())
            product_name = random.choice(products_df['Name'].tolist())
            quantity = random.randint(1, max_quantity)

            row_idx = products_df[products_df['Name'] == product_name].index
            if not row_idx.empty:
                online_stock = products_df.at[row_idx[0], 'Stock_Online']
                store_stock = products_df.at[row_idx[0], 'Stock_Store']
                total_stock = online_stock + store_stock

                if total_stock >= quantity:
                    # Reduce stock
                    if online_stock >= quantity:
                        products_df.at[row_idx[0], 'Stock_Online'] -= quantity
                    else:
                        products_df.at[row_idx[0], 'Stock_Online'] = 0
                        products_df.at[row_idx[0], 'Stock_Store'] -= (quantity - online_stock)

                    # Update customer history
                    cust_idx = customers_df[customers_df['CustomerID'] == customer_id].index
                    history = customers_df.at[cust_idx[0], 'History']
                    history_list = history.split(",") if history else []
                    history_list.append(product_name)
                    customers_df.at[cust_idx[0], 'History'] = ",".join(history_list)

                    # Log the sale
                    sales_log = pd.concat([sales_log, pd.DataFrame([{
                        'Timestamp': pd.Timestamp.now(),
                        'CustomerID': customer_id,
                        'Product': product_name,
                        'Quantity': quantity
                    }])], ignore_index=True)

                    print(f"💵 Sale: {quantity} x {product_name} for Customer {customer_id}")
                else:
                    print(f"⚠️ Not enough stock for {product_name}. Available: {total_stock}")

            time.sleep(interval)

    thread = threading.Thread(target=simulation_loop)
    thread.daemon = True
    thread.start()
    print(f"⏱ Automated sales simulation with log started! New sale every {interval} seconds.")

