# -----------------------------
# Step 2: Function to display Low Stock Forecast
# -----------------------------
def live_low_stock_forecast_chart(interval=10, threshold_days=5):
    """
    Predicts products likely to run out within `threshold_days` based on average daily sales.
    """
    def update_loop():
        global sales_log
        while True:
            with out_low_stock_forecast:
                clear_output(wait=True)

                if not sales_log.empty:
                    forecast_data = {}
                    current_time = pd.Timestamp.now()

                    for product in products_df['Name']:
                        # Filter sales for this product
                        product_sales = sales_log[sales_log['Product'] == product]
                        if not product_sales.empty:
                            # Calculate average quantity sold per day
                            product_sales['Date'] = product_sales['Timestamp'].dt.date
                            daily_sales = product_sales.groupby('Date')['Quantity'].sum()
                            avg_daily_sales = daily_sales.mean()

                            # Predict days until out of stock
                            total_stock = products_df.loc[products_df['Name'] == product, ['Stock_Online', 'Stock_Store']].sum(axis=1).values[0]
                            if avg_daily_sales > 0:
                                days_left = total_stock / avg_daily_sales
                                forecast_data[product] = days_left

                    # Plot products with days_left <= threshold_days
                    if forecast_data:
                        low_stock_products = {k:v for k,v in forecast_data.items() if v <= threshold_days}
                        if low_stock_products:
                            plt.figure(figsize=(6,3))
                            plt.bar(low_stock_products.keys(), low_stock_products.values(), color='orange')
                            plt.title(f"Low Stock Forecast (≤ {threshold_days} days)")
                            plt.ylabel("Estimated Days Left")
                            plt.show()
                        else:
                            print(f"✅ No products forecasted to run out within {threshold_days} days.")
                    else:
                        print("ℹ️ Not enough sales data for forecasting.")

            time.sleep(interval)

    thread = threading.Thread(target=update_loop)
    thread.daemon = True
    thread.start()
    print(f"⏱ Live Low Stock Forecast chart updating every {interval} seconds...")

