import smtplib
from email.mime.multipart import MIMEMultipart
from email.mime.text import MIMEText

# -----------------------------
# Step 1: Email Configuration
# -----------------------------
EMAIL_ADDRESS = "your_email@gmail.com"       # Replace with sender email
EMAIL_PASSWORD = "your_app_password"         # Use App Password if Gmail
MANAGER_EMAIL = "manager_email@gmail.com"    # Recipient email

# -----------------------------
# Step 2: Function to send email
# -----------------------------
def send_email(subject, body, recipient=MANAGER_EMAIL):
    try:
        msg = MIMEMultipart()
        msg['From'] = EMAIL_ADDRESS
        msg['To'] = recipient
        msg['Subject'] = subject
        msg.attach(MIMEText(body, 'plain'))

        server = smtplib.SMTP('smtp.gmail.com', 587)
        server.starttls()
        server.login(EMAIL_ADDRESS, EMAIL_PASSWORD)
        server.send_message(msg)
        server.quit()
        print(f"📧 Email sent to {recipient}: {subject}")
    except Exception as e:
        print(f"❌ Failed to send email: {e}")

# -----------------------------
# Step 3: Function to check low-stock and send alerts
# -----------------------------
def email_low_stock_alert(threshold=3):
    critical_items = products_df[
        (products_df['Stock_Online'] + products_df['Stock_Store']) <= threshold
    ]

    if not critical_items.empty:
        body = "⚠️ Low Stock Alert ⚠️\n\nThe following products are low in stock:\n"
        for _, row in critical_items.iterrows():
            total_stock = row['Stock_Online'] + row['Stock_Store']
            body += f"- {row['Name']} (Total Stock: {total_stock})\n"
        send_email(subject="Low Stock Alert", body=body)
    else:
        print("✅ No low-stock products to send email for.")

# -----------------------------
# Step 4: Automated email notification loop
# -----------------------------
def automated_low_stock_email(interval=60):
    def email_loop():
        while True:
            email_low_stock_alert(threshold=3)
            time.sleep(interval)  # send alert every `interval` seconds (e.g., 1 min)

    thread = threading.Thread(target=email_loop)
    thread.daemon = True
    thread.start()
    print(f"⏱ Automated low-stock email notifications every {interval} seconds started!")

# -----------------------------
# Step 5: Start automated email alerts
# -----------------------------
automated_low_stock_email(interval=60)

# -----------------------------
# Step 1: Function to send customer-specific low-stock email
# -----------------------------
def email_customer_low_stock_alert(customer_id, threshold=3):
    customer = customers_df[customers_df['CustomerID'] == customer_id]
    if customer.empty:
        return

    email_address = customer.get('Email', [None])[0]  # assuming Email column exists
    if not email_address:
        print(f"❌ No email for Customer {customer_id}")
        return

    # Combine wishlist and history
    items_to_check = []
    history = customer['History'].values[0].split(",") if customer['History'].values[0] else []
    wishlist = customer['Wishlist'].values[0].split(",") if customer['Wishlist'].values[0] else []
    items_to_check = list(set(history + wishlist))

    low_stock_items = []
    for item in items_to_check:
        row = products_df[products_df['Name'].str.contains(item, case=False, na=False)]
        if not row.empty:
            total_stock = row['Stock_Online'].values[0] + row['Stock_Store'].values[0]
            if total_stock <= threshold:
                low_stock_items.append(f"{row['Name'].values[0]} (Stock: {total_stock})")

    if low_stock_items:
        body = f"⚠️ Low Stock Alert for you ⚠️\n\nThe following items you purchased or wished for are running low:\n"
        body += "\n".join(low_stock_items)
        send_email(subject=f"Low Stock Notification for {customer['Name'].values[0]}", body=body, recipient=email_address)
    else:
        print(f"✅ No low-stock items to notify Customer {customer_id}")

# -----------------------------
# Step 2: Automated customer-specific email loop
# -----------------------------
def automated_customer_email(interval=120, threshold=3):
    def email_loop():
        while True:
            for cid in customers_df['CustomerID']:
                email_customer_low_stock_alert(cid, threshold=threshold)
            time.sleep(interval)  # check every `interval` seconds

    thread = threading.Thread(target=email_loop)
    thread.daemon = True
    thread.start()
    print(f"⏱ Automated customer-specific low-stock emails every {interval} seconds started!")

# -----------------------------
# Step 3: Start customer-specific email notifications
# -----------------------------
automated_customer_email(interval=120, threshold=3)

from reportlab.lib.pagesizes import A4
from reportlab.pdfgen import canvas
from reportlab.lib.utils import ImageReader
import io

# -----------------------------
# Step 1: Function to capture matplotlib figure as image
# -----------------------------
def fig_to_image(fig):
    buf = io.BytesIO()
    fig.savefig(buf, format='PNG', bbox_inches='tight')
    buf.seek(0)
    return ImageReader(buf)

# -----------------------------
# Step 2: Function to generate PDF report
# -----------------------------
def generate_pdf_report(customer_id, filename="report.pdf"):
    c = canvas.Canvas(filename, pagesize=A4)
    width, height = A4
    y = height - 50

    # Title
    c.setFont("Helvetica-Bold", 16)
    c.drawString(50, y, f"📊 Retail Analytics Report for Customer {customer_id}")
    y -= 40

    # Recommendations
    recs = recommendation_agent(customer_id)
    c.setFont("Helvetica-Bold", 12)
    c.drawString(50, y, "🎯 Top Recommendations:")
    y -= 20
    c.setFont("Helvetica", 10)
    for idx, row in recs.iterrows():
        c.drawString(60, y, f"- {row['Name']} | Category: {row['Category']} | Price: {row['Price']} | Stock Online: {row['Stock_Online']} | Stock Store: {row['Stock_Store']}")
        y -= 15

    y -= 20
    # Low-stock alerts
    c.setFont("Helvetica-Bold", 12)
    c.drawString(50, y, "⚠️ Low Stock Alerts:")
    y -= 20
    c.setFont("Helvetica", 10)
    for item in products_df.itertuples():
        total_stock = item.Stock_Online + item.Stock_Store
        if total_stock <= 3:
            c.drawString(60, y, f"- {item.Name} | Total Stock: {total_stock}")
            y -= 15

    # Sales Trend Chart
    if not sales_log.empty:
        fig, ax = plt.subplots(figsize=(6,3))
        sales_summary = sales_log.groupby('Product')['Quantity'].sum()
        ax.bar(sales_summary.index, sales_summary.values, color='green')
        ax.set_title("Sales Trend")
        ax.set_ylabel("Quantity Sold")
        fig.tight_layout()
        y -= 20
        c.drawImage(fig_to_image(fig), 50, y-150, width=500, height=150)
        plt.close(fig)
        y -= 160

    # Top Customers Chart
    if not sales_log.empty:
        fig, ax = plt.subplots(figsize=(6,3))
        top_customers = sales_log.groupby('CustomerID')['Quantity'].sum().sort_values(ascending=False)
        ax.bar(top_customers.index, top_customers.values, color='purple')
        ax.set_title("Top Customers")
        ax.set_ylabel("Quantity Purchased")
        fig.tight_layout()
        c.drawImage(fig_to_image(fig), 50, y-150, width=500, height=150)
        plt.close(fig)
        y -= 160

    # Low Stock Forecast Chart
    forecast_data = {}
    for product in products_df['Name']:
        product_sales = sales_log[sales_log['Product'] == product]
        if not product_sales.empty:
            product_sales['Date'] = product_sales['Timestamp'].dt.date
            daily_sales = product_sales.groupby('Date')['Quantity'].sum()
            avg_daily_sales = daily_sales.mean()
            total_stock = products_df.loc[products_df['Name']==product, ['Stock_Online','Stock_Store']].sum(axis=1).values[0]
            if avg_daily_sales > 0:
                days_left = total_stock / avg_daily_sales
                forecast_data[product] = days_left
    low_stock_products = {k:v for k,v in forecast_data.items() if v <= 5}
    if low_stock_products:
        fig, ax = plt.subplots(figsize=(6,3))
        ax.bar(low_stock_products.keys(), low_stock_products.values(), color='orange')
        ax.set_title("Low Stock Forecast (≤ 5 days)")
        ax.set_ylabel("Estimated Days Left")
        fig.tight_layout()
        c.drawImage(fig_to_image(fig), 50, y-150, width=500, height=150)
        plt.close(fig)
        y -= 160

    c.save()
    print(f"✅ PDF report generated: {filename}")

# -----------------------------
# Step 3: Example usage
# -----------------------------
generate_pdf_report(customer_id="C001", filename="customer_C001_report.pdf")

import smtplib
from email.mime.multipart import MIMEMultipart
from email.mime.text import MIMEText
from email.mime.base import MIMEBase
from email import encoders
import pandas as pd # Added import for pandas

# -----------------------------
# Step 0: Sample Data (Defining necessary variables here)
# -----------------------------
# Ensure these are defined or accessible from previous cells
# For this cell to run independently, I'll include minimal samples:
if 'customers_df' not in globals():
    customers_df = pd.DataFrame({
        'CustomerID': ['C001', 'C002'],
        'Name': ['Aditi', 'Rahul'],
        'History': ['Kurta,Jeans', 'Shirt,Sneakers'],
        'Email': ['customer1@example.com', 'customer2@example.com'],  # replace with real emails
        'Loyalty': ['Gold', 'Silver'],
        'Points': [200, 80]
    })

# Define email credentials and manager email
EMAIL_ADDRESS = "your_email@gmail.com"       # replace with sender email
EMAIL_PASSWORD = "your_app_password"         # Use App Password if Gmail
MANAGER_EMAIL = "manager_email@gmail.com"    # Recipient email


# -----------------------------
# Step 1: Function to send PDF via email
# -----------------------------
def email_pdf_report(customer_id, filename="report.pdf"):
    # Get customer email, fallback to manager if not available
    customer = customers_df[customers_df['CustomerID'] == customer_id]
    recipient_email = MANAGER_EMAIL
    if 'Email' in customer.columns and not customer['Email'].empty and customer['Email'].values[0]:
        recipient_email = customer['Email'].values[0]
    elif 'Email' in customer.columns and customer['Email'].empty:
         print(f"❌ No email found for Customer {customer_id}, sending to manager.")
    else:
         print(f"❌ 'Email' column not found or empty for Customer {customer_id}, sending to manager.")


    try:
        msg = MIMEMultipart()
        msg['From'] = EMAIL_ADDRESS
        msg['To'] = recipient_email
        msg['Subject'] = f"📄 Daily Retail Report for {customer['Name'].values[0]}"

        # Email body
        body = f"Hello {customer['Name'].values[0]},\n\nPlease find attached your daily retail report.\n\nBest regards,\nRetail Analytics Team"
        msg.attach(MIMEText(body, 'plain'))

        # Attach PDF
        try:
            with open(filename, 'rb') as f:
                part = MIMEBase('application', 'octet-stream')
                part.set_payload(f.read())
                encoders.encode_base64(part)
                part.add_header('Content-Disposition', f'attachment; filename={filename}')
                msg.attach(part)
        except FileNotFoundError:
            print(f"❌ Error attaching PDF: File '{filename}' not found.")
            # Optionally, send the email without the attachment if the file is missing
            # server = smtplib.SMTP('smtp.gmail.com', 587)
            # server.starttls()
            # server.login(EMAIL_ADDRESS, EMAIL_PASSWORD)
            # server.send_message(msg)
            # server.quit()
            return # Exit the function if PDF is missing


        # Send email
        server = smtplib.SMTP('smtp.gmail.com', 587)
        server.starttls()
        server.login(EMAIL_ADDRESS, EMAIL_PASSWORD)
        server.send_message(msg)
        server.quit()
        print(f"📧 PDF report emailed to {recipient_email}")
    except Exception as e:
        print(f"❌ Failed to send PDF report: {e}")

# -----------------------------
# Step 2: Example usage
# -----------------------------
# Make sure the PDF file 'customer_C001_report.pdf' exists before running this.
# You can generate it using the generate_pdf_report function in a previous cell.
email_pdf_report(customer_id="C001", filename="customer_C001_report.pdf")

