if 'customers_df' not in globals():
    customers_df = pd.DataFrame({
        'CustomerID': ['C001', 'C002', 'C003', 'C004', 'C005'],
        'Name': ['Aditi', 'Rahul', 'Meera', 'Arjun', 'Neha'],
        'Loyalty': ['Gold', 'Silver', 'Gold', 'Bronze', 'Silver'],
        'Points': [200, 80, 300, 40, 120],
        'History': ['Kurta,Jeans', 'Shirt,Sneakers', 'Saree,Heels', 'Tshirt,Shorts', 'Dress,Handbag'],
        'Email': ['customer1@example.com', 'customer2@example.com', 'customer3@example.com', 'customer4@example.com', 'customer5@example.com']
    })

if 'products_df' not in globals():
    products_df = pd.DataFrame({
        'SKU': ['P001','P002','P003','P004','P005'],
        'Name': ['Party Wear Dress','Shirt','Sneakers','Kurta','Jeans'],
        'Category': ['Women','Men','Unisex','Women','Unisex'],
        'Price': [2500,1200,3000,1800,1800],
        'Stock_Online':[5,2,3,6,4],
        'Stock_Store':[2,5,1,2,4]
    })


# -----------------------------
# Step 1: Recommendation Agent (Defining recommendation_agent here for independence)
# -----------------------------
def recommendation_agent(customer_id, top_k=3):
    customer = customers_df[customers_df['CustomerID'] == customer_id]
    if customer.empty:
        return pd.DataFrame()

    history = customer['History'].values[0].split(",")
    candidate_products = products_df[~products_df['Name'].isin(history)]

    preferred_categories = []
    for item in history:
        match = products_df[products_df['Name'].str.contains(item, case=False, na=False)]
        if not match.empty:
            preferred_categories.extend(match['Category'].tolist())

    if preferred_categories:
        candidate_products = candidate_products[
            (candidate_products['Category'].isin(preferred_categories)) |
            (candidate_products['Category'] == "Unisex")
        ]

    candidate_products = candidate_products[
        (candidate_products['Stock_Online'] > 0) | (candidate_products['Stock_Store'] > 0)
    ]

    recs = candidate_products.sort_values(
        by=["Stock_Online", "Stock_Store", "Price"], ascending=[False, False, True]
    ).head(top_k)

    return recs[["SKU", "Name", "Category", "Price", "Stock_Online", "Stock_Store"]]


# -----------------------------
# Step 2: Analytics Agent (Defining analytics_agent here for independence)
# -----------------------------
def analytics_agent():
    report = {}

    # 1. Top-selling products (based on frequency in history)
    all_history = []
    for h in customers_df['History']:
        if isinstance(h, str):
            all_history.extend(h.split(","))
        elif isinstance(h, list):
            all_history.extend(h)

    if all_history:
        top_selling = pd.Series(all_history).value_counts().head(5).to_dict()
        report['Top Selling Products'] = top_selling
    else:
        report['Top Selling Products'] = "No history data available."


    # 2. Low stock items (threshold: <=3 online + store)
    products_df['Total_Stock'] = products_df['Stock_Online'] + products_df['Stock_Store']
    low_stock = products_df[products_df['Total_Stock'] <= 3][['Name','Total_Stock']].to_dict('records')
    report['Low Stock Items'] = low_stock

    # 3. Loyalty level distribution
    loyalty_dist = customers_df['Loyalty'].value_counts().to_dict()
    report['Loyalty Distribution'] = loyalty_dist

    # 4. Avg customer points
    avg_points = customers_df['Points'].mean()
    report['Average Loyalty Points'] = avg_points

    return report

# -----------------------------
# Step 3: Function to capture matplotlib figure as image
# -----------------------------
def fig_to_image(fig):
    buf = io.BytesIO()
    fig.savefig(buf, format='PNG', bbox_inches='tight')
    buf.seek(0)
    return ImageReader(buf)

