import ipywidgets as widgets
from IPython.display import display, clear_output
import matplotlib.pyplot as plt
import threading
import time

# -----------------------------
# Step 1: Dropdown for Customers
# -----------------------------
customer_dropdown = widgets.Dropdown(
    options=customers_df['CustomerID'].tolist(),
    description='Customer:',
    value='C001'
)

# -----------------------------
# Step 2: Function to display live analytics dashboard
# -----------------------------
def live_customer_dashboard(customer_id, interval=10):
    stop_flag = threading.Event()

    def dashboard_loop():
        while not stop_flag.is_set():
            clear_output(wait=True)
            display(customer_dropdown)
            print(f"📊 Live Analytics Dashboard for Customer: {customer_id}")

            # Filter sales for this customer
            customer_sales = sales_log[sales_log['CustomerID'] == customer_id]

            # Top Products Purchased
            top_products = customer_sales.groupby('Product')['Quantity'].sum().sort_values(ascending=False)
            print("\n🛒 Top Products Purchased:")
            display(top_products)
            if not top_products.empty:
                plt.figure(figsize=(5,3))
                plt.bar(top_products.index, top_products.values, color='skyblue')
                plt.title("Top Products Purchased")
                plt.ylabel("Quantity")
                plt.show()

            # Recommendations
            recs = recommendation_agent(customer_id)
            print("\n🎯 Top Recommendations:")
            display(recs)

            # Low Stock Alerts
            low_stock = products_df[(products_df['Stock_Online'] + products_df['Stock_Store']) <= 3]
            print("\n⚠️ Low Stock Products:")
            display(low_stock[['Name','Stock_Online','Stock_Store']])

            # PDF Button
            pdf_button = widgets.Button(description=f"Generate PDF for {customer_id}", button_style='success')
            def on_pdf_click(b):
                generate_and_email_pdf(customer_id)
            pdf_button.on_click(on_pdf_click)
            display(pdf_button)

            time.sleep(interval)

    thread = threading.Thread(target=dashboard_loop)
    thread.start()

    return stop_flag  # Return flag to stop dashboard manually

# -----------------------------
# Step 3: Dropdown change updates the customer ID
# -----------------------------
current_stop_flag = None

def on_change(change):
    global current_stop_flag
    if change['type'] == 'change' and change['name'] == 'value':
        if current_stop_flag:
            current_stop_flag.set()  # stop previous dashboard thread
        customer_id = change['new']
        current_stop_flag = live_customer_dashboard(customer_id, interval=10)

customer_dropdown.observe(on_change)

# -----------------------------
# Step 4: Display dropdown and start dashboard
# -----------------------------
display(customer_dropdown)
current_stop_flag = live_customer_dashboard(customer_dropdown.value, interval=10)

