# -----------------------------
# Loyalty Agent
# -----------------------------
def loyalty_agent(customer_id):
    # Get customer info
    customer = customers_df[customers_df['CustomerID'] == customer_id]
    if customer.empty:
        print(f"❌ Customer {customer_id} not found.")
        return None

    name = customer['Name'].values[0]
    loyalty_tier = customer['Loyalty'].values[0]
    points = customer['Points'].values[0]

    # Determine benefits based on loyalty tier
    benefits = ""
    if loyalty_tier == "Gold":
        benefits = "10% discount on all items, priority support, free shipping"
    elif loyalty_tier == "Silver":
        benefits = "5% discount on selected items, standard support"
    else:
        benefits = "Standard membership benefits"

    # Determine points needed for next tier
    tier_points = {"Bronze": 0, "Silver": 100, "Gold": 200}
    next_tier = None
    points_needed = 0
    if loyalty_tier == "Bronze":
        next_tier = "Silver"
        points_needed = tier_points["Silver"] - points
    elif loyalty_tier == "Silver":
        next_tier = "Gold"
        points_needed = tier_points["Gold"] - points
    elif loyalty_tier == "Gold":
        next_tier = "Max Tier"
        points_needed = 0

    # Personalized recommendation based on loyalty
    recs = recommendation_agent(customer_id)

    # Loyalty summary
    loyalty_summary = {
        "CustomerID": customer_id,
        "Name": name,
        "Loyalty Tier": loyalty_tier,
        "Points": points,
        "Benefits": benefits,
        "Next Tier": next_tier,
        "Points Needed for Next Tier": points_needed,
        "Top Recommendations": recs
    }

    return loyalty_summary

