# Example usage
# -----------------------------
customer_loyalty = loyalty_agent("C001")
print("📋 Loyalty Summary:")
for k,v in customer_loyalty.items():
    if k != "Top Recommendations":
        print(f"{k}: {v}")
print("\n🎯 Top Recommendations:")
display(customer_loyalty["Top Recommendations"])

