# -----------------------------
# Generate PDF with Loyalty Insights
# -----------------------------
def generate_loyalty_pdf(customer_id, filename=None):
    if filename is None:
        filename = f"/content/customer_{customer_id}_report.pdf"

    c = canvas.Canvas(filename, pagesize=A4)
    width, height = A4
    y = height - 50

    c.setFont("Helvetica-Bold", 16)
    c.drawString(50, y, f"📊 Retail Analytics & Loyalty Report for Customer {customer_id}")
    y -= 40

    # Loyalty summary
    loyalty_summary = loyalty_agent(customer_id)
    if loyalty_summary:
        c.setFont("Helvetica-Bold", 12)
        c.drawString(50, y, "📋 Loyalty Summary:")
        y -= 20
        c.setFont("Helvetica", 10)
        for k,v in loyalty_summary.items():
            if k != "Top Recommendations":
                c.drawString(60, y, f"{k}: {v}")
                y -= 15
        y -= 10

        # Top Recommendations
        c.setFont("Helvetica-Bold", 12)
        c.drawString(50, y, "🎯 Top Recommendations:")
        y -= 20
        c.setFont("Helvetica", 10)
        recs = loyalty_summary["Top Recommendations"]
        for idx, row in recs.iterrows():
            c.drawString(60, y, f"- {row['Name']} | {row['Category']} | Price: {row['Price']}")
            y -= 15
        y -= 20

    # Optional: add charts for top purchases
    customer_sales = sales_log[sales_log['CustomerID'] == customer_id]
    if not customer_sales.empty:
        top_products = customer_sales.groupby('Product')['Quantity'].sum()
        fig, ax = plt.subplots(figsize=(6,3))
        ax.bar(top_products.index, top_products.values, color='skyblue')
        ax.set_title("Top Products Purchased")
        fig.tight_layout()

        # Convert chart to image and embed in PDF
        buf = io.BytesIO()
        fig.savefig(buf, format='PNG', bbox_inches='tight')
        buf.seek(0)
        img = ImageReader(buf)
        c.drawImage(img, 50, y-150, width=500, height=150)
        plt.close(fig)
        y -= 160

    # Low stock alert
    low_stock = products_df[(products_df['Stock_Online'] + products_df['Stock_Store']) <= 3]
    if not low_stock.empty:
        c.setFont("Helvetica-Bold", 12)
        c.drawString(50, y, "⚠️ Low Stock Products:")
        y -= 20
        c.setFont("Helvetica", 10)
        for item in low_stock.itertuples():
            c.drawString(60, y, f"- {item.Name} | Stock Online: {item.Stock_Online} | Stock Store: {item.Stock_Store}")
            y -= 15

    c.save()
    print(f"✅ Loyalty PDF report generated: {filename}")

