from reportlab.pdfgen import canvas
from reportlab.lib.pagesizes import A4
from reportlab.lib.utils import ImageReader

def generate_system_report_pdf(filename="/content/retail_system_report.pdf"):
    c = canvas.Canvas(filename, pagesize=A4)
    width, height = A4
    y = height - 50

    # Title
    c.setFont("Helvetica-Bold", 18)
    c.drawString(50, y, "📊 Retail Analytics & Loyalty System - Documentation")
    y -= 40

    # Workflow Diagram
    c.setFont("Helvetica-Bold", 14)
    c.drawString(50, y, "1️⃣ Workflow Diagram")
    y -= 20
    workflow_path = "/content/retail_analytics_loyalty_workflow_colored.png"
    try:
        img = ImageReader(workflow_path)
        c.drawImage(img, 50, y-300, width=500, height=300)
        y -= 320
    except:
        c.drawString(50, y, "⚠️ Workflow diagram not found")
        y -= 20

    # Sequence Diagram
    c.setFont("Helvetica-Bold", 14)
    c.drawString(50, y, "2️⃣ PDF & Email Sequence Diagram")
    y -= 20
    sequence_path = "/content/pdf_email_sequence.png"
    try:
        img = ImageReader(sequence_path)
        c.drawImage(img, 50, y-300, width=500, height=300)
        y -= 320
    except:
        c.drawString(50, y, "⚠️ Sequence diagram not found")
        y -= 20

    c.save()
    print(f"✅ System report PDF generated: {filename}")

# Generate the combined report
generate_system_report_pdf("/content/retail_system_report.pdf")

# Function to send customer report + system documentation together
def send_full_report_to_customers():
    system_pdf = "/content/retail_system_report.pdf"

    for customer_id in customers_df['CustomerID']:
        # Generate individual customer PDF
        customer_pdf = f"/content/customer_{customer_id}_report.pdf"
        generate_loyalty_pdf(customer_id, customer_pdf)

        # Send email
        try:
            to_email = customers_df.loc[customers_df['CustomerID']==customer_id, 'Email'].values[0]

            # Compose email
            msg = MIMEMultipart()
            msg['From'] = EMAIL_ADDRESS
            msg['To'] = to_email
            msg['Subject'] = f"Retail & Loyalty Report for {customer_id}"
            body = f"Hi {customer_id},\nPlease find attached your personal report and system documentation."
            msg.attach(MIMEText(body, 'plain'))

            # Attach customer PDF
            with open(customer_pdf, 'rb') as f:
                part = MIMEBase('application', 'octet-stream')
                part.set_payload(f.read())
                encoders.encode_base64(part)
                part.add_header('Content-Disposition', f"attachment; filename={customer_pdf}")
                msg.attach(part)

            # Attach system documentation PDF
            with open(system_pdf, 'rb') as f:
                part = MIMEBase('application', 'octet-stream')
                part.set_payload(f.read())
                encoders.encode_base64(part)
                part.add_header('Content-Disposition', f"attachment; filename={system_pdf}")
                msg.attach(part)

            # Send email
            server = smtplib.SMTP('smtp.gmail.com', 587)
            server.starttls()
            server.login(EMAIL_ADDRESS, EMAIL_PASSWORD)
            server.send_message(msg)
            server.quit()
            print(f"✅ Email sent to {customer_id} with all reports")
        except:
            print(f"⚠️ Could not send email to {customer_id}")

# Example usage
send_full_report_to_customers()

