# Scheduler for Full Reports (Customer + System Documentation)
# -----------------------------

# Configurable interval in seconds
FULL_REPORT_INTERVAL = 60  # e.g., every 60 seconds

# Schedule the automated full report email
schedule.every(FULL_REPORT_INTERVAL).seconds.do(send_full_report_to_customers)

