import datetime

def fulfilment_agent_with_delivery(customer_id, order_items):
    """
    Fulfilment Agent:
    - Checks stock
    - Updates stock
    - Adds expected delivery date
    """
    report = []

    for item_name, qty in order_items.items():
        product_row = products_df[products_df['Name'] == item_name]

        if product_row.empty:
            report.append({'Item': item_name, 'Status': '❌ Not Found'})
            continue

        stock_online = int(product_row['Stock_Online'].values[0])
        stock_store = int(product_row['Stock_Store'].values[0])
        total_stock = stock_online + stock_store

        if total_stock >= qty:
            # Deduct stock
            if stock_online >= qty:
                products_df.loc[products_df['Name'] == item_name, 'Stock_Online'] -= qty
            else:
                remaining = qty - stock_online
                products_df.loc[products_df['Name'] == item_name, 'Stock_Online'] = 0
                products_df.loc[products_df['Name'] == item_name, 'Stock_Store'] -= remaining

            # Estimate delivery: 2 days for in-stock, 5 days if low stock
            delivery_days = 2 if total_stock >= 5 else 5
            delivery_date = datetime.date.today() + datetime.timedelta(days=delivery_days)
            report.append({'Item': item_name, 'Status': '✅ Fulfilled', 'Delivery_Date': str(delivery_date)})

        else:
            report.append({'Item': item_name, 'Status': '⚠️ Insufficient Stock', 'Available': total_stock})

    return pd.DataFrame(report)

