from reportlab.lib.pagesizes import A4
from reportlab.pdfgen import canvas
from reportlab.lib.utils import ImageReader
import io

# Helper: convert matplotlib figure into image
def fig_to_image(fig):
    buf = io.BytesIO()
    fig.savefig(buf, format='PNG', bbox_inches='tight')
    buf.seek(0)
    return ImageReader(buf)

def generate_fulfilment_pdf(customer_id, order_items, filename="fulfilment_report.pdf"):
    c = canvas.Canvas(filename, pagesize=A4)
    width, height = A4
    y = height - 50

    # Title
    c.setFont("Helvetica-Bold", 16)
    c.drawString(50, y, f"📦 Fulfilment Report for Customer {customer_id}")
    y -= 40

    # Order Fulfilment Section
    c.setFont("Helvetica-Bold", 12)
    c.drawString(50, y, "🎯 Order Fulfilment Status:")
    y -= 20

    report = fulfilment_agent_with_delivery(customer_id, order_items)
    c.setFont("Helvetica", 10)
    for idx, row in report.iterrows():
        if row['Status'] == '✅ Fulfilled':
            c.drawString(60, y, f"- {row['Item']} | {row['Status']} | Delivery: {row['Delivery_Date']}")
        else:
            c.drawString(60, y, f"- {row['Item']} | {row['Status']} | Ordered: {row['Ordered_Qty']} | Available: {row['Available']}")
        y -= 15

    y -= 20

    # Low Stock Alerts Section
    c.setFont("Helvetica-Bold", 12)
    c.drawString(50, y, "⚠️ Low Stock Alerts:")
    y -= 20

    low_stock = products_df[(products_df['Stock_Online'] + products_df['Stock_Store']) <= 3]
    c.setFont("Helvetica", 10)
    if low_stock.empty:
        c.drawString(60, y, "✅ All products have sufficient stock")
        y -= 15
    else:
        for idx, row in low_stock.iterrows():
            total = row['Stock_Online'] + row['Stock_Store']
            c.drawString(60, y, f"- {row['Name']} | Total Stock: {total}")
            y -= 15

    # Low Stock Chart
    if not low_stock.empty:
        fig, ax = plt.subplots(figsize=(5,3))
        total_stock = low_stock['Stock_Online'] + low_stock['Stock_Store']
        ax.bar(low_stock['Name'], total_stock, color='red')
        ax.set_title("Low-Stock Products")
        ax.set_ylabel("Total Stock")
        fig.tight_layout()
        c.drawImage(fig_to_image(fig), 50, y-150, width=400, height=150)
        plt.close(fig)
        y -= 170

    c.save()
    print(f"✅ PDF fulfilment report generated: {filename}")

