import schedule
import time
import threading

def scheduled_fulfilment_job():
    order_items = {'Jeans': 2, 'Shirt': 1}  # Example order
    filename = f"/content/fulfilment_report_{int(time.time())}.pdf"
    generate_fulfilment_pdf("C001", order_items, filename)
    print(f"📄 Scheduled Fulfilment Report Generated: {filename}")

# Run every 10 seconds (for demo)
schedule.every(10).seconds.do(scheduled_fulfilment_job)

def run_scheduler():
    print("⏳ Fulfilment report scheduler started... (every 10s)")
    while True:
        schedule.run_pending()
        time.sleep(1)

# Start in background thread so notebook remains usable
thread = threading.Thread(target=run_scheduler, daemon=True)
thread.start()

