#!/usr/bin/env python3
"""
Flask Web App for Low-Stock Alerts and PDF Reports
--------------------------------------------------

Features:
- Upload inventory CSV file (must have: SKU, Name, Category, Stock_Online, Stock_Store, Price).
- Choose low-stock threshold.
- Generate PDF report with tables + chart.
- Download the generated report.

Run:
    python app.py
Then open http://127.0.0.1:5000 in your browser.
"""

import os
import pandas as pd
import matplotlib.pyplot as plt
from flask import Flask, request, render_template_string, send_from_directory

from reportlab.lib import colors
from reportlab.lib.pagesizes import A4, landscape
from reportlab.lib.styles import getSampleStyleSheet
from reportlab.platypus import SimpleDocTemplate, Paragraph, Spacer, Table, TableStyle, Image

# ---------------- Flask Setup ----------------
app = Flask(__name__)
UPLOAD_FOLDER = "./uploads"
REPORT_FOLDER = "./reports"
os.makedirs(UPLOAD_FOLDER, exist_ok=True)
os.makedirs(REPORT_FOLDER, exist_ok=True)

# ---------------- Helpers ----------------
def generate_chart(df: pd.DataFrame, threshold: int, outdir: str):
    chart_path = os.path.join(outdir, "chart.png")
    fig, ax = plt.subplots(figsize=(9, 4))
    bars = ax.bar(df["SKU"], df["Total_Stock"])

    for i, (_, row) in enumerate(df.iterrows()):
        if row["Total_Stock"] <= threshold:
            bars[i].set_hatch("///")
            ax.text(i, row["Total_Stock"] + 0.2, "LOW", ha="center", va="bottom", fontsize=9)

    ax.set_xlabel("SKU")
    ax.set_ylabel("Total Stock (Online + Store)")
    ax.set_title(f"Stock Levels (Low-stock threshold = {threshold})")
    ax.grid(axis="y", linestyle="--", linewidth=0.5, alpha=0.6)
    ymax = max(df["Total_Stock"].max() + 2, threshold + 4)
    ax.set_ylim(0, ymax)

    fig.tight_layout()
    fig.savefig(chart_path, dpi=150)
    plt.close(fig)
    return chart_path


def generate_pdf_report(df: pd.DataFrame, alerts: pd.DataFrame, chart_path: str, threshold: int, outdir: str):
    pdf_path = os.path.join(outdir, "low_stock_report.pdf")
    doc = SimpleDocTemplate(pdf_path, pagesize=landscape(A4))

    styles = getSampleStyleSheet()
    elements = []

    elements.append(Paragraph("<b>Low-Stock Alert Report</b>", styles["Title"]))
    elements.append(Spacer(1, 12))
    summary_text = f"Threshold = <b>{threshold}</b>. Found <b>{len(alerts)}</b> low-stock items."
    elements.append(Paragraph(summary_text, styles["Normal"]))
    elements.append(Spacer(1, 12))

    # Full Inventory
    elements.append(Paragraph("<b>Full Inventory</b>", styles["Heading2"]))
    inv_table = Table([df.columns.tolist()] + df.values.tolist())
    inv_table.setStyle(TableStyle([
        ("BACKGROUND", (0, 0), (-1, 0), colors.grey),
        ("TEXTCOLOR", (0, 0), (-1, 0), colors.whitesmoke),
        ("ALIGN", (0, 0), (-1, -1), "CENTER"),
        ("GRID", (0, 0), (-1, -1), 0.5, colors.black),
    ]))
    elements.append(inv_table)
    elements.append(Spacer(1, 20))

    # Low-stock table
    elements.append(Paragraph("<b>Low-Stock Items</b>", styles["Heading2"]))
    if alerts.empty:
        elements.append(Paragraph("✅ No low-stock items.", styles["Normal"]))
    else:
        alert_table = Table([alerts.columns.tolist()] + alerts.values.tolist())
        alert_table.setStyle(TableStyle([
            ("BACKGROUND", (0, 0), (-1, 0), colors.red),
            ("TEXTCOLOR", (0, 0), (-1, 0), colors.whitesmoke),
            ("ALIGN", (0, 0), (-1, -1), "CENTER"),
            ("GRID", (0, 0), (-1, -1), 0.5, colors.black),
        ]))
        elements.append(alert_table)
    elements.append(Spacer(1, 20))

    # Chart
    elements.append(Paragraph("<b>Stock Chart</b>", styles["Heading2"]))
    elements.append(Image(chart_path, width=500, height=250))

    doc.build(elements)
    return pdf_path


# ---------------- Flask Routes ----------------
HTML_TEMPLATE = """
<!DOCTYPE html>
<html>
<head>
    <title>Low-Stock Alert System</title>
</head>
<body style="font-family: Arial, sans-serif; margin: 40px;">
    <h1>📊 Low-Stock Alert System</h1>
    <form method="POST" enctype="multipart/form-data">
        <label>Upload Inventory CSV:</label><br>
        <input type="file" name="file" required><br><br>

        <label>Low-stock threshold:</label><br>
        <input type="number" name="threshold" value="4"><br><br>

        <input type="submit" value="Generate Report">
    </form>
    {% if report_path %}
        <h2>✅ Report Generated</h2>
        <a href="{{ url_for('download_report') }}">Download PDF Report</a>
    {% endif %}
</body>
</html>
"""

@app.route("/", methods=["GET", "POST"])
def index():
    report_path = None
    if request.method == "POST":
        # Save uploaded file
        file = request.files["file"]
        threshold = int(request.form.get("threshold", 4))
        filepath = os.path.join(UPLOAD_FOLDER, file.filename)
        file.save(filepath)

        # Load CSV
        df = pd.read_csv(filepath)
        df["Total_Stock"] = df["Stock_Online"].astype(int) + df["Stock_Store"].astype(int)
        df["Low_Stock"] = df["Total_Stock"] <= threshold
        alerts = df[df["Low_Stock"]].copy().reset_index(drop=True)

        # Generate chart & PDF
        chart_path = generate_chart(df, threshold, REPORT_FOLDER)
        pdf_path = generate_pdf_report(df, alerts, chart_path, threshold, REPORT_FOLDER)
        report_path = pdf_path

    return render_template_string(HTML_TEMPLATE, report_path=report_path)


@app.route("/download")
def download_report():
    return send_from_directory(REPORT_FOLDER, "low_stock_report.pdf", as_attachment=True)


# ---------------- Run ----------------
if __name__ == "__main__":
    app.run(debug=True)

#!/usr/bin/env python3
# app.py
import os
import uuid
from flask import Flask, request, render_template_string, send_from_directory, url_for, abort
from werkzeug.utils import secure_filename
import pandas as pd
import matplotlib.pyplot as plt
from reportlab.lib import colors
from reportlab.lib.pagesizes import A4, landscape
from reportlab.lib.styles import getSampleStyleSheet
from reportlab.platypus import SimpleDocTemplate, Paragraph, Spacer, Table, TableStyle, Image

ALLOWED_EXTENSIONS = {'csv'}

def allowed_file(filename):
    return '.' in filename and filename.rsplit('.', 1)[1].lower() in ALLOWED_EXTENSIONS

UPLOAD_FOLDER = os.environ.get('UPLOAD_FOLDER', './uploads')
REPORT_FOLDER = os.environ.get('REPORT_FOLDER', './reports')
os.makedirs(UPLOAD_FOLDER, exist_ok=True)
os.makedirs(REPORT_FOLDER, exist_ok=True)

app = Flask(__name__)
app.config['UPLOAD_FOLDER'] = UPLOAD_FOLDER

def generate_chart(df, threshold, outdir, uid):
    chart_path = os.path.join(outdir, f"chart_{uid}.png")
    fig, ax = plt.subplots(figsize=(9, 4))
    bars = ax.bar(df["SKU"], df["Total_Stock"])
    for i, (_, row) in enumerate(df.iterrows()):
        if row["Total_Stock"] <= threshold:
            bars[i].set_hatch("///")
            ax.text(i, row["Total_Stock"] + 0.2, "LOW", ha="center", va="bottom", fontsize=9)
    ax.set_xlabel("SKU")
    ax.set_ylabel("Total Stock (Online + Store)")
    ax.set_title(f"Stock Levels (threshold = {threshold})")
    ax.grid(axis="y", linestyle="--", linewidth=0.5, alpha=0.6)
    ymax = max(df["Total_Stock"].max() + 2, threshold + 4)
    ax.set_ylim(0, ymax)
    fig.tight_layout()
    fig.savefig(chart_path, dpi=150)
    plt.close(fig)
    return chart_path

def generate_pdf_report(df, alerts, chart_path, threshold, outdir, uid):
    pdf_path = os.path.join(outdir, f"low_stock_report_{uid}.pdf")
    doc = SimpleDocTemplate(pdf_path, pagesize=landscape(A4))
    styles = getSampleStyleSheet()
    elements = []
    elements.append(Paragraph("<b>Low-Stock Alert Report</b>", styles["Title"]))
    elements.append(Spacer(1, 12))
    elements.append(Paragraph(f"Threshold = <b>{threshold}</b>. Found <b>{len(alerts)}</b> low-stock item(s).", styles["Normal"]))
    elements.append(Spacer(1, 12))

    # Full Inventory table
    elements.append(Paragraph("<b>Full Inventory</b>", styles["Heading2"]))
    inv_table = Table([df.columns.tolist()] + df.values.tolist())
    inv_table.setStyle(TableStyle([
        ("BACKGROUND", (0, 0), (-1, 0), colors.grey),
        ("TEXTCOLOR", (0, 0), (-1, 0), colors.whitesmoke),
        ("ALIGN", (0, 0), (-1, -1), "CENTER"),
        ("GRID", (0, 0), (-1, -1), 0.5, colors.black)
    ]))
    elements.append(inv_table)
    elements.append(Spacer(1, 20))

    # Low-stock table
    elements.append(Paragraph("<b>Low-Stock Items</b>", styles["Heading2"]))
    if alerts.empty:
        elements.append(Paragraph("✅ No low-stock items.", styles["Normal"]))
    else:
        alert_table = Table([alerts.columns.tolist()] + alerts.values.tolist())
        alert_table.setStyle(TableStyle([
            ("BACKGROUND", (0, 0), (-1, 0), colors.red),
            ("TEXTCOLOR", (0, 0), (-1, 0), colors.whitesmoke),
            ("ALIGN", (0, 0), (-1, -1), "CENTER"),
            ("GRID", (0, 0), (-1, -1), 0.5, colors.black)
        ]))
        elements.append(alert_table)
    elements.append(Spacer(1, 20))

    elements.append(Paragraph("<b>Stock Chart</b>", styles["Heading2"]))
    elements.append(Image(chart_path, width=500, height=250))

    doc.build(elements)
    return pdf_path

HTML_TEMPLATE = """
<!doctype html>
<title>Low-Stock Alert</title>
<h1>Upload inventory CSV</h1>
<form method=post enctype=multipart/form-data>
  <input type=file name=file accept=".csv" required>
  <br><br>
  Threshold: <input type=number name=threshold value=4 min=0>
  <br><br>
  <input type=submit value="Generate PDF Report">
</form>
{% if report_filename %}
  <h2>Report ready</h2>
  <a href="{{ url_for('download_report', filename=report_filename) }}">Download report</a>
{% endif %}
"""

@app.route("/", methods=["GET", "POST"])
def index():
    report_filename = None
    if request.method == "POST":
        file = request.files.get("file")
        if not file or not allowed_file(file.filename):
            return "Upload a CSV file (.csv) with columns SKU, Name, Category, Stock_Online, Stock_Store", 400

        uid = uuid.uuid4().hex
        safe_name = secure_filename(file.filename)
        upload_name = f"{uid}_{safe_name}"
        upload_path = os.path.join(app.config['UPLOAD_FOLDER'], upload_name)
        file.save(upload_path)

        # read CSV and sanity-check columns
        df = pd.read_csv(upload_path)
        required = {"SKU", "Stock_Online", "Stock_Store"}
        if not required.issubset(set(df.columns)):
            return f"CSV missing required columns: {required}. Found columns: {list(df.columns)}", 400

        # coerce numeric columns, compute totals
        df["Stock_Online"] = pd.to_numeric(df["Stock_Online"], errors="coerce").fillna(0).astype(int)
        df["Stock_Store"] = pd.to_numeric(df["Stock_Store"], errors="coerce").fillna(0).astype(int)
        df["Total_Stock"] = df["Stock_Online"] + df["Stock_Store"]

        threshold = int(request.form.get("threshold", 4))
        df["Low_Stock"] = df["Total_Stock"] <= threshold
        # build alerts subset with common columns if available
        alerts = df.loc[df["Low_Stock"], ["SKU", *(c for c in ["Name", "Category"] if c in df.columns), "Stock_Online", "Stock_Store", "Total_Stock"]].reset_index(drop=True)

        chart_path = generate_chart(df, threshold, REPORT_FOLDER, uid)
        pdf_path = generate_pdf_report(df, alerts, chart_path, threshold, REPORT_FOLDER, uid)

        report_filename = os.path.basename(pdf_path)

    return render_template_string(HTML_TEMPLATE, report_filename=report_filename)

@app.route("/download/<path:filename>")
def download_report(filename):
    # Safe send from REPORT_FOLDER
    full = os.path.join(REPORT_FOLDER, filename)
    if not os.path.exists(full):
        abort(404)
    return send_from_directory(REPORT_FOLDER, filename, as_attachment=True)

# NOTE: app.run is only for local debugging; do NOT use the dev server in production.
if __name__ == "__main__":
    app.run(host="0.0.0.0", port=int(os.environ.get("PORT", 5000)))

