import ipywidgets as widgets
from IPython.display import display, clear_output
import matplotlib.pyplot as plt

# Fulfilment widgets
product_options = products_df['Name'].tolist()
product_select = widgets.SelectMultiple(
    options=product_options,
    description='Order Items:',
    value=[]
)
quantity_text = widgets.Text(
    description='Qty (comma-separated)',
    placeholder='e.g., 2,1'
)
fulfil_button = widgets.Button(description="Process Order", button_style='info')
fulfil_output = widgets.Output()

# Low-stock alert outputs
low_stock_table_output = widgets.Output()
low_stock_chart_output = widgets.Output()
LOW_STOCK_THRESHOLD = 3

# Function to update live low-stock alerts
def update_low_stock_dashboard():
    with low_stock_table_output:
        clear_output()
        low_stock = products_df[(products_df['Stock_Online'] + products_df['Stock_Store']) <= LOW_STOCK_THRESHOLD]
        if low_stock.empty:
            print("✅ All products have sufficient stock")
        else:
            print(f"⚠️ Low Stock Products (≤{LOW_STOCK_THRESHOLD}):")
            display(low_stock[['Name','Stock_Online','Stock_Store']])

    with low_stock_chart_output:
        clear_output()
        low_stock = products_df[(products_df['Stock_Online'] + products_df['Stock_Store']) <= LOW_STOCK_THRESHOLD]
        if not low_stock.empty:
            plt.figure(figsize=(6,3))
            total_stock = low_stock['Stock_Online'] + low_stock['Stock_Store']
            plt.bar(low_stock['Name'], total_stock, color='red')
            plt.title(f"⚠️ Low-Stock Products (≤{LOW_STOCK_THRESHOLD})")
            plt.ylabel("Total Stock")
            plt.xticks(rotation=45)
            plt.show()
        else:
            print(f"✅ No products with total stock ≤ {LOW_STOCK_THRESHOLD}")

# Fulfilment order processing
def process_order_dashboard(b):
    with fulfil_output:
        clear_output()
        customer_id = 'C001'  # example
        selected_items = list(product_select.value)
        try:
            qty_list = [int(x.strip()) for x in quantity_text.value.split(",")]
        except:
            print("⚠️ Invalid quantity input")
            return
        if len(selected_items) != len(qty_list):
            print("⚠️ Number of items and quantities mismatch")
            return

        order_dict = dict(zip(selected_items, qty_list))
