import smtplib
from email.message import EmailMessage

def send_email_report(to_email, subject, body, attachment_path):
    msg = EmailMessage()
    msg['From'] = 'your_email@gmail.com'          # Replace with sender email
    msg['To'] = to_email
    msg['Subject'] = subject
    msg.set_content(body)

    # Attach PDF
    with open(attachment_path, 'rb') as f:
        file_data = f.read()
        file_name = attachment_path.split('/')[-1]
    msg.add_attachment(file_data, maintype='application', subtype='pdf', filename=file_name)

    # Send email via Gmail SMTP
    try:
        with smtplib.SMTP_SSL('smtp.gmail.com', 465) as smtp:
            smtp.login('your_email@gmail.com', 'your_app_password')  # Use app password
            smtp.send_message(msg)
        print(f"✅ Email sent to {to_email} with attachment {file_name}")
    except Exception as e:
        print("❌ Failed to send email:", e)

