import pandas as pd
import matplotlib.pyplot as plt
import ipywidgets as widgets
from IPython.display import display, clear_output
from reportlab.pdfgen import canvas
from reportlab.lib.pagesizes import A4
from reportlab.lib.utils import ImageReader
from email.message import EmailMessage
import smtplib
import io
import random
import time

# Customers
customers_df = pd.DataFrame([
    {'CustomerID':'C001', 'Name':'Aditi', 'Loyalty':'Gold', 'Points':200, 'History':'Kurta,Jeans'},
    {'CustomerID':'C002', 'Name':'Rahul', 'Loyalty':'Silver', 'Points':80, 'History':'Shirt,Sneakers'}
])

# Products
products_df = pd.DataFrame([
    {'SKU':'P001','Name':'Party Wear Dress','Category':'Women','Price':2500,'Stock_Online':5,'Stock_Store':2},
    {'SKU':'P002','Name':'Shirt','Category':'Men','Price':1200,'Stock_Online':10,'Stock_Store':8},
    {'SKU':'P003','Name':'Sneakers','Category':'Unisex','Price':1500,'Stock_Online':2,'Stock_Store':1},
    {'SKU':'P004','Name':'Kurta','Category':'Unisex','Price':900,'Stock_Online':0,'Stock_Store':5},
    {'SKU':'P005','Name':'Jeans','Category':'Unisex','Price':1800,'Stock_Online':6,'Stock_Store':4}
])

# Sales log
sales_log = pd.DataFrame(columns=['Timestamp','CustomerID','Product','Quantity'])

def recommendation_agent(customer_id, top_k=3):
    customer = customers_df[customers_df['CustomerID']==customer_id]
    if customer.empty: return pd.DataFrame()
    history = customer['History'].values[0].split(",")
    candidate_products = products_df[~products_df['Name'].isin(history)]
    preferred_categories = []
    for item in history:
        match = products_df[products_df['Name'].str.contains(item, case=False, na=False)]
        if not match.empty: preferred_categories.extend(match['Category'].tolist())
    if preferred_categories:
        candidate_products = candidate_products[
            (candidate_products['Category'].isin(preferred_categories)) |
            (candidate_products['Category']=="Unisex")
        ]
    candidate_products = candidate_products[
        (candidate_products['Stock_Online']>0) | (candidate_products['Stock_Store']>0)
    ]
    recs = candidate_products.sort_values(
        by=["Stock_Online","Stock_Store","Price"], ascending=[False,False,True]
    ).head(top_k)
    return recs[["SKU","Name","Category","Price","Stock_Online","Stock_Store"]]

def fulfilment_agent_with_delivery(customer_id, order_dict):
    report = []
    for product, qty in order_dict.items():
        stock_row = products_df[products_df['Name']==product].iloc[0]
        available_stock = stock_row['Stock_Online'] + stock_row['Stock_Store']
        delivered_qty = min(qty, available_stock)
        delivery_days = 2 if delivered_qty <= stock_row['Stock_Online'] else 5
        report.append({'Product':product,'Ordered':qty,'Delivered':delivered_qty,'Delivery_Days':delivery_days})
        # Update stock
        products_df.loc[products_df['Name']==product,'Stock_Online'] -= min(delivered_qty, stock_row['Stock_Online'])
        remaining = delivered_qty - min(delivered_qty, stock_row['Stock_Online'])
        products_df.loc[products_df['Name']==product,'Stock_Store'] -= remaining
    return pd.DataFrame(report)

def generate_fulfilment_pdf(customer_id, order_dict, filename="report.pdf"):
    c = canvas.Canvas(filename, pagesize=A4)
    width, height = A4
    y = height-50
    c.setFont("Helvetica-Bold",16)
    c.drawString(50,y,f"🛒 Fulfilment Report for Customer {customer_id}")
    y -= 40
    c.setFont("Helvetica",12)
    for product, qty in order_dict.items():
        c.drawString(60,y,f"- {product} | Quantity: {qty}")
        y -= 15
    c.save()
    print(f"✅ PDF report generated: {filename}")

def send_email_report(to_email, subject, body, attachment_path):
    msg = EmailMessage()
    msg['From'] = 'your_email@gmail.com'
    msg['To'] = to_email
    msg['Subject'] = subject
    msg.set_content(body)
    with open(attachment_path,'rb') as f:
        msg.add_attachment(f.read(), maintype='application', subtype='pdf', filename=attachment_path.split('/')[-1])
    try:
        with smtplib.SMTP_SSL('smtp.gmail.com',465) as smtp:
            smtp.login('your_email@gmail.com','your_app_password')
            smtp.send_message(msg)
        print(f"✅ Email sent to {to_email}")
    except Exception as e:
        print("❌ Email failed:",e)

