# ----------------------------
# FastAPI app
# ----------------------------
app = FastAPI(title="Retail Master API", version="1.0")

# ----------------------------
# Sample Data
# ----------------------------
customers_df = pd.DataFrame([
    {"CustomerID": "C001", "Name": "Aditi", "Loyalty": "Gold", "Points": 200, "History": "Kurta,Jeans"},
    {"CustomerID": "C002", "Name": "Rahul", "Loyalty": "Silver", "Points": 80, "History": "Shirt,Sneakers"}
])

products_df = pd.DataFrame([
    {"SKU": "P001", "Name": "Party Wear Dress", "Category": "Women", "Price": 2500, "Stock_Online": 5, "Stock_Store": 2},
    {"SKU": "P002", "Name": "Kurta", "Category": "Men", "Price": 1200, "Stock_Online": 4, "Stock_Store": 3},
    {"SKU": "P003", "Name": "Jeans", "Category": "Unisex", "Price": 1800, "Stock_Online": 6, "Stock_Store": 4},
    {"SKU": "P004", "Name": "Shirt", "Category": "Men", "Price": 900, "Stock_Online": 2, "Stock_Store": 1},
    {"SKU": "P005", "Name": "Sneakers", "Category": "Unisex", "Price": 1500, "Stock_Online": 5, "Stock_Store": 2}
])

sales_log = pd.DataFrame(columns=["CustomerID", "Product", "Quantity", "Timestamp"])

# ----------------------------
# Pydantic Models
# ----------------------------
class OrderRequest(BaseModel):
    customer_id: str
    items: dict   # { "Kurta": 2, "Jeans": 1 }

# ----------------------------
# Endpoints
# ----------------------------
@app.get("/")
def root():
    return {"message": "Welcome to Retail Master API"}

@app.get("/analytics/{customer_id}")
def analytics(customer_id: str):
    cust = customers_df[customers_df["CustomerID"] == customer_id]
    if cust.empty:
        return {"error": "Customer not found"}
    history = cust["History"].values[0].split(",")
    return {
        "Customer": cust["Name"].values[0],
        "History": history,
        "Total Purchases": len(history)
    }

@app.get("/loyalty/{customer_id}")
def loyalty(customer_id: str):
    cust = customers_df[customers_df["CustomerID"] == customer_id]
    if cust.empty:
        return {"error": "Customer not found"}
    return {
        "Customer": cust["Name"].values[0],
        "Loyalty Tier": cust["Loyalty"].values[0],
        "Points": int(cust["Points"].values[0])
    }

@app.post("/order")
def place_order(order: OrderRequest):
    global sales_log, products_df, customers_df
    cust = customers_df[customers_df["CustomerID"] == order.customer_id]
    if cust.empty:
        return {"error": "Customer not found"}
    order_summary = []
    total_cost = 0
    for item_name, qty in order.items.items():
        product = products_df[products_df["Name"] == item_name]
        if product.empty:
            order_summary.append({"Item": item_name, "Status": "Not Found"})
            continue
        stock_online = int(product["Stock_Online"].values[0])
        if stock_online < qty:
            order_summary.append({"Item": item_name, "Status": "Insufficient Stock"})
            continue
        # Deduct stock
        products_df.loc[products_df["Name"] == item_name, "Stock_Online"] -= qty
        # Update loyalty points (10% of total cost as points)
        price = int(product["Price"].values[0])
        total_cost += price * qty
        customers_df.loc[customers_df["CustomerID"] == order.customer_id, "Points"] += int(price * qty * 0.1)
        # Log the sale
        new_sale = {
            "CustomerID": order.customer_id,
            "Product": item_name,
            "Quantity": qty,
            "Timestamp": datetime.datetime.now().strftime("%Y-%m-%d %H:%M:%S")
        }
        sales_log = pd.concat([sales_log, pd.DataFrame([new_sale])], ignore_index=True)
        order_summary.append({"Item": item_name, "Quantity": qty, "Status": "Ordered"})
    return {
        "Customer": cust["Name"].values[0],
        "Order Summary": order_summary,
        "Total Cost": total_cost,
        "Updated Points": int(customers_df.loc[customers_df["CustomerID"] == order.customer_id, "Points"].values[0])
    }

@app.get("/recommend/{customer_id}")
def recommend(customer_id: str):
    cust = customers_df[customers_df["CustomerID"] == customer_id]
    if cust.empty:
        return {"error": "Customer not found"}
    history = cust["History"].values[0].split(",")
    all_products = products_df["Name"].tolist()
    recommendations = [p for p in all_products if p not in history]
    random.shuffle(recommendations)
    return {
        "Customer": cust["Name"].values[0],
        "Recommendations": recommendations[:2]
    }

@app.get("/inventory")
def inventory():
    low_stock = products_df[(products_df["Stock_Online"] <= 2) | (products_df["Stock_Store"] <= 1)]
    return {
        "Low Stock Items": low_stock.to_dict(orient="records"),
        "Total Products": len(products_df)
    }

@app.get("/sales_log")
def get_sales_log():
    return sales_log.to_dict(orient="records")

# ----------------------------
# Run FastAPI
# ----------------------------
uvicorn.run(app, host="0.0.0.0", port=8000)

import streamlit as st
import pandas as pd
import random
import datetime

# ----------------------------
# Sample Data
# ----------------------------
customers_df = pd.DataFrame([
    {"CustomerID": "C001", "Name": "Aditi", "Loyalty": "Gold", "Points": 200, "History": "Kurta,Jeans"},
    {"CustomerID": "C002", "Name": "Rahul", "Loyalty": "Silver", "Points": 80, "History": "Shirt,Sneakers"}
])

products_df = pd.DataFrame([
    {"SKU": "P001", "Name": "Party Wear Dress", "Category": "Women", "Price": 2500, "Stock_Online": 5, "Stock_Store": 2},
    {"SKU": "P002", "Name": "Kurta", "Category": "Men", "Price": 1200, "Stock_Online": 4, "Stock_Store": 3},
    {"SKU": "P003", "Name": "Jeans", "Category": "Unisex", "Price": 1800, "Stock_Online": 6, "Stock_Store": 4},
    {"SKU": "P004", "Name": "Shirt", "Category": "Men", "Price": 900, "Stock_Online": 2, "Stock_Store": 1},
    {"SKU": "P005", "Name": "Sneakers", "Category": "Unisex", "Price": 1500, "Stock_Online": 5, "Stock_Store": 2}
])

# ----------------------------
# Streamlit UI
# ----------------------------
st.title("Retail Master Dashboard")

menu = ["Analytics", "Loyalty", "Place Order", "Recommendations", "Inventory"]
choice = st.sidebar.selectbox("Choose Action", menu)

# Analytics
if choice == "Analytics":
    cust_id = st.text_input("Enter Customer ID", "C001")
    cust = customers_df[customers_df["CustomerID"] == cust_id]
    if not cust.empty:
        history = cust["History"].values[0].split(",")
        st.write("Customer:", cust["Name"].values[0])
        st.write("Purchase History:", history)
        st.write("Total Purchases:", len(history))
    else:
        st.write("Customer not found")

# Loyalty
if choice == "Loyalty":
    cust_id = st.text_input("Enter Customer ID", "C001")
    cust = customers_df[customers_df["CustomerID"] == cust_id]
    if not cust.empty:
        st.write("Customer:", cust["Name"].values[0])
        st.write("Loyalty Tier:", cust["Loyalty"].values[0])
        st.write("Points:", cust["Points"].values[0])
    else:
        st.write("Customer not found")

# Place Order
if choice == "Place Order":
    cust_id = st.text_input("Customer ID", "C001")
    st.write("Available Products:")
    st.dataframe(products_df[["Name", "Price", "Stock_Online"]])
    item = st.selectbox("Select Item", products_df["Name"].tolist())
    qty = st.number_input("Quantity", min_value=1, max_value=10, value=1)
    if st.button("Place Order"):
        cust = customers_df[customers_df["CustomerID"] == cust_id]
        if cust.empty:
            st.write("Customer not found")
        else:
            product = products_df[products_df["Name"] == item]
            if product["Stock_Online"].values[0] >= qty:
                products_df.loc[products_df["Name"] == item, "Stock_Online"] -= qty
                st.write(f"Order Placed! {qty} x {item}")
                # Update loyalty points
                customers_df.loc[customers_df["CustomerID"] == cust_id, "Points"] += int(product["Price"].values[0]*0.1*qty)
            else:
                st.write("Insufficient Stock")

# Recommendations
if choice == "Recommendations":
    cust_id = st.text_input("Enter Customer ID", "C001")
    cust = customers_df[customers_df["CustomerID"] == cust_id]
    if not cust.empty:
        history = cust["History"].values[0].split(",")
        recommendations = [p for p in products_df["Name"].tolist() if p not in history]
        random.shuffle(recommendations)
        st.write("Recommended Products:", recommendations[:2])
    else:
        st.write("Customer not found")

# Inventory
if choice == "Inventory":
    low_stock = products_df[(products_df["Stock_Online"] <= 2) | (products_df["Stock_Store"] <= 1)]
    st.write("Low Stock Items:")
    st.dataframe(low_stock)

