def delivery_estimate(customer_id, item, qty):
    shipping_days = random.randint(2,7)  # Random 2-7 days for demo
    return f"Estimated delivery for {qty} x {item}: {shipping_days} days"

def sales_history():
    if sales_log.empty:
        return "No sales yet"
    return sales_log.to_dict(orient='records')

def advanced_recommendations(customer_id):
    cust = customers_df[customers_df["CustomerID"]==customer_id]
    if cust.empty: return "Customer not found"
    history = cust["History"].values[0].split(",")
    recs = products_df[~products_df["Name"].isin(history)]["Name"].tolist()
    if cust["Loyalty"].values[0]=="Gold":
        recs = recs[:3]  # Gold customers get more options
    else:
        recs = recs[:2]
    return recs

def order_and_alert(customer_id, item, qty):
    message = place_order(customer_id, item, qty)
    product_stock = products_df.loc[products_df["Name"]==item, "Stock_Online"].values[0]
    if product_stock <= 2:
        message += f"\n⚠️ Alert: Low stock for {item}!"
    return message

def check_loyalty_submit_flag(customer_id):
    output = check_loyalty(customer_id)
    flag = "✅ Submit Flag Cleared"
    return f"{output}\n{flag}"

