import gradio as gr
import pandas as pd
import random
import datetime
import matplotlib.pyplot as plt

# ----------------------------
# Sample Data
# ----------------------------
customers_df = pd.DataFrame([
    {"CustomerID": "C001", "Name": "Aditi", "Loyalty": "Gold", "Points": 200, "History": "Kurta,Jeans"},
    {"CustomerID": "C002", "Name": "Rahul", "Loyalty": "Silver", "Points": 80, "History": "Shirt,Sneakers"},
    {"CustomerID": "C003", "Name": "Simran", "Loyalty": "Gold", "Points": 150, "History": "Jeans,Sneakers"}
])

products_df = pd.DataFrame([
    {"Name": "Party Wear Dress", "Price": 2500, "Stock_Online": 5},
    {"Name": "Kurta", "Price": 1200, "Stock_Online": 4},
    {"Name": "Jeans", "Price": 1800, "Stock_Online": 6},
    {"Name": "Shirt", "Price": 900, "Stock_Online": 2},
    {"Name": "Sneakers", "Price": 1500, "Stock_Online": 5}
])

# Pre-populated Sales Log
sales_log = pd.DataFrame([
    {"CustomerID":"C001", "Product":"Kurta", "Quantity":1, "Timestamp":"2025-09-26 12:00:00"},
    {"CustomerID":"C002", "Product":"Sneakers", "Quantity":2, "Timestamp":"2025-09-26 13:30:00"},
    {"CustomerID":"C003", "Product":"Jeans", "Quantity":1, "Timestamp":"2025-09-26 14:00:00"}
])

# ----------------------------
# Global Submit Flag
# ----------------------------
submit_flag = {"status": "❌ Not Submitted"}

# ----------------------------
# Functions
# ----------------------------
def update_submit_flag():
    submit_flag["status"] = "✅ Submitted"
    return submit_flag["status"]

def get_submit_flag():
    return submit_flag["status"]

def check_analytics(customer_id):
    cust = customers_df[customers_df["CustomerID"]==customer_id]
    if cust.empty: return "Customer not found"
    history = cust["History"].values[0].split(",")
    return f"Customer: {cust['Name'].values[0]}\nPurchase History: {history}\nTotal Purchases: {len(history)}\nSubmit Status: {get_submit_flag()}"

def check_loyalty(customer_id):
    cust = customers_df[customers_df["CustomerID"]==customer_id]
    if cust.empty: return "Customer not found"
    return f"{cust['Name'].values[0]} - {cust['Loyalty'].values[0]} Tier, Points: {cust['Points'].values[0]}\nSubmit Status: {get_submit_flag()}"

def place_order(customer_id, item, qty):
    global products_df, customers_df, sales_log
    cust = customers_df[customers_df["CustomerID"]==customer_id]
    if cust.empty: return "Customer not found"
    product = products_df[products_df["Name"]==item]
    if product.empty: return "Item not found"
    stock = int(product["Stock_Online"].values[0])
    if stock < qty: return f"Insufficient stock for {item}"

    # Update stock and points
    products_df.loc[products_df["Name"]==item,"Stock_Online"] -= qty
    customers_df.loc[customers_df["CustomerID"]==customer_id,"Points"] += int(product["Price"].values[0]*0.1*qty)

    # Log the sale
    new_sale = {"CustomerID": customer_id, "Product": item, "Quantity": qty,
                "Timestamp": datetime.datetime.now().strftime("%Y-%m-%d %H:%M:%S")}
    sales_log = pd.concat([sales_log, pd.DataFrame([new_sale])], ignore_index=True)

    # Delivery estimate
    delivery_days = random.randint(2,5) + qty // 3
    delivery_msg = f"Estimated delivery for {qty} x {item}: {delivery_days} days"

    # Low stock alert
    stock_after = products_df.loc[products_df["Name"]==item,"Stock_Online"].values[0]
    alert_msg = f"⚠️ Low Stock Alert!" if stock_after <= 2 else ""

    return f"Order Placed: {qty} x {item}\nUpdated Points: {customers_df.loc[customers_df['CustomerID']==customer_id,'Points'].values[0]}\n{delivery_msg}\n{alert_msg}\nSubmit Status: {get_submit_flag()}"

def recommend_items(customer_id):
    cust = customers_df[customers_df["CustomerID"]==customer_id]
    if cust.empty: return "Customer not found"
    history = cust["History"].values[0].split(",")
    recs = [p for p in products_df["Name"].tolist() if p not in history]
    random.shuffle(recs)
    return recs[:2]

def low_inventory():
    low_stock = products_df[products_df["Stock_Online"]<=2]
    if low_stock.empty:
        return "All products in good stock."
    return low_stock.to_dict(orient='records')

def sales_history_table():
    if sales_log.empty:
        return pd.DataFrame(columns=["CustomerID","Product","Quantity","Timestamp"])
    return sales_log

# ----------------------------
# Chart Functions
# ----------------------------
def top_selling_products_chart():
    if sales_log.empty:
        fig, ax = plt.subplots()
        ax.text(0.5,0.5,"No sales yet",ha="center",va="center", fontsize=14)
        ax.axis("off")
        return fig
    df = sales_log.groupby("Product")["Quantity"].sum().sort_values(ascending=False)
    fig, ax = plt.subplots()
    df.plot(kind="bar", ax=ax, color="skyblue")
    ax.set_ylabel("Total Quantity Sold")
    ax.set_title("Top-Selling Products")
    return fig

def loyalty_distribution_chart():
    df = customers_df["Loyalty"].value_counts()
    fig, ax = plt.subplots()
    df.plot(kind="pie", autopct="%1.1f%%", ax=ax, colors=["gold","silver","lightgreen"])
    ax.set_ylabel("")
    ax.set_title("Loyalty Tier Distribution")
    return fig

def stock_levels_chart():
    fig, ax = plt.subplots()
    products_df.set_index("Name")["Stock_Online"].plot(kind="bar", color="orange", ax=ax)
    ax.set_ylabel("Stock Available")
    ax.set_title("Stock Levels")
    return fig

# ----------------------------
# Gradio Interface
# ----------------------------
with gr.Blocks() as demo:
    gr.Markdown("# Retail Master Dashboard (Submit Flag + Charts)")

    # Submit Button (global)
    submit_btn = gr.Button("Submit Assignment")
    submit_status = gr.Textbox(label="Submit Status", value=get_submit_flag())
    submit_btn.click(update_submit_flag, inputs=None, outputs=submit_status)

    with gr.Tab("Analytics"):
        cid_input = gr.Textbox(label="Customer ID", value="C001")
        analytics_btn = gr.Button("Check Analytics")
        analytics_output = gr.Textbox()
        analytics_btn.click(check_analytics, inputs=cid_input, outputs=analytics_output)

    with gr.Tab("Loyalty"):
        cid_input2 = gr.Textbox(label="Customer ID", value="C001")
        loyalty_btn = gr.Button("Check Loyalty")
        loyalty_output = gr.Textbox()
        loyalty_btn.click(check_loyalty, inputs=cid_input2, outputs=loyalty_output)

    with gr.Tab("Place Order"):
        cid_input3 = gr.Textbox(label="Customer ID", value="C001")
        item_input = gr.Dropdown(choices=products_df["Name"].tolist(), label="Item")
        qty_input = gr.Slider(1,10,1,label="Quantity")
        order_btn = gr.Button("Place Order")
        order_output = gr.Textbox()
        order_btn.click(place_order, inputs=[cid_input3,item_input,qty_input], outputs=order_output)

    with gr.Tab("Recommendations"):
        cid_input4 = gr.Textbox(label="Customer ID", value="C001")
        rec_btn = gr.Button("Get Recommendations")
        rec_output = gr.Textbox()
        rec_btn.click(recommend_items, inputs=cid_input4, outputs=rec_output)

    with gr.Tab("Inventory"):
        inv_btn = gr.Button("Check Low Inventory")
        inv_output = gr.Textbox()
        inv_btn.click(low_inventory, inputs=None, outputs=inv_output)

    with gr.Tab("Sales Log"):
        sales_btn = gr.Button("View Sales Log")
        sales_output = gr.Dataframe(headers=["CustomerID","Product","Quantity","Timestamp"])
        sales_btn.click(sales_history_table, inputs=None, outputs=sales_output)

    with gr.Tab("Charts"):
        top_chart_btn = gr.Button("Top-Selling Products")
        top_chart_output = gr.Plot()
        top_chart_btn.click(top_selling_products_chart, inputs=None, outputs=top_chart_output)

        loyalty_chart_btn = gr.Button("Loyalty Distribution")
        loyalty_chart_output = gr.Plot()
        loyalty_chart_btn.click(loyalty_distribution_chart, inputs=None, outputs=loyalty_chart_output)

        stock_chart_btn = gr.Button("Stock Levels")
        stock_chart_output = gr.Plot()
        stock_chart_btn.click(stock_levels_chart, inputs=None, outputs=stock_chart_output)

demo.launch(share=True)

