import gradio as gr
import pandas as pd
import random
import datetime
import matplotlib.pyplot as plt

# ----------------------------
# Sample Data
# ----------------------------
customers_df = pd.DataFrame([
    {"CustomerID": "C001", "Name": "Aditi", "Loyalty": "Gold", "Points": 200, "History": "Kurta,Jeans"},
    {"CustomerID": "C002", "Name": "Rahul", "Loyalty": "Silver", "Points": 80, "History": "Shirt,Sneakers"},
    {"CustomerID": "C003", "Name": "Simran", "Loyalty": "Gold", "Points": 150, "History": "Jeans,Sneakers"}
])

products_df = pd.DataFrame([
    {"Name": "Party Wear Dress", "Price": 2500, "Stock_Online": 5},
    {"Name": "Kurta", "Price": 1200, "Stock_Online": 4},
    {"Name": "Jeans", "Price": 1800, "Stock_Online": 6},
    {"Name": "Shirt", "Price": 900, "Stock_Online": 2},
    {"Name": "Sneakers", "Price": 1500, "Stock_Online": 5}
])

sales_log = pd.DataFrame(columns=["CustomerID","Product","Quantity","Timestamp"])
submit_flag = {"status": "❌ Not Submitted"}

# ----------------------------
# Functions
# ----------------------------
def update_submit_flag():
    submit_flag["status"] = "✅ Submitted"
    return submit_flag["status"]

def get_submit_flag():
    return submit_flag["status"]

def dashboard_summary():
    total_sales = sales_log["Quantity"].sum() if not sales_log.empty else 0
    merged = pd.merge(sales_log, products_df, left_on="Product", right_on="Name", how="left")
    total_revenue = (merged["Quantity"]*merged["Price"]).sum() if not merged.empty else 0
    low_stock = products_df[products_df["Stock_Online"]<=2]["Name"].tolist()
    total_customers = customers_df["CustomerID"].nunique()

    summary = f"""**📊 Dashboard Summary**
- Total Sales: {total_sales}
- Total Revenue: ₹{total_revenue}
- Total Customers: {total_customers}
- Low Stock Items: {low_stock if low_stock else 'None'}
- Submit Status: {get_submit_flag()}"""
    return summary

def place_order(customer_id, item, qty):
    global products_df, customers_df, sales_log
    cust = customers_df[customers_df["CustomerID"]==customer_id]
    if cust.empty: return "❌ Customer not found"
    product = products_df[products_df["Name"]==item]
    if product.empty: return "❌ Item not found"
    stock = int(product["Stock_Online"].values[0])
    if stock < qty: return f"⚠️ Insufficient stock for {item}"

    # Update stock & points
    products_df.loc[products_df["Name"]==item, "Stock_Online"] -= qty
    customers_df.loc[customers_df["CustomerID"]==customer_id,"Points"] += int(product["Price"].values[0]*0.1*qty)

    # Log sale
    sales_log.loc[len(sales_log)] = [customer_id, item, qty, datetime.datetime.now().strftime("%Y-%m-%d %H:%M:%S")]

    # Delivery estimate
    tier = cust["Loyalty"].values[0]
    base_days = random.randint(2,5) + qty//3
    if tier=="Gold": delivery_days = max(1, base_days-1)
    elif tier=="Silver": delivery_days = base_days
    else: delivery_days = base_days+1

    # Low stock alert
    alert_msg = "⚠️ Low Stock Alert!" if products_df.loc[products_df["Name"]==item,"Stock_Online"].values[0]<=2 else ""

    return f"""✅ Order Placed: {qty} x {item}
**Updated Points:** {customers_df.loc[customers_df["CustomerID"]==customer_id,"Points"].values[0]}
**Estimated Delivery:** {delivery_days} days
{alert_msg}
Submit Status: {get_submit_flag()}"""

def check_analytics(customer_id):
    cust = customers_df[customers_df["CustomerID"]==customer_id]
    if cust.empty: return "❌ Customer not found"
    history = cust["History"].values[0].split(",")
    return f"**Customer:** {cust['Name'].values[0]}\n**Purchase History:** {history}\n**Total Purchases:** {len(history)}\nSubmit Status: {get_submit_flag()}"

def check_loyalty(customer_id):
    cust = customers_df[customers_df["CustomerID"]==customer_id]
    if cust.empty: return "❌ Customer not found"
    return f"**{cust['Name'].values[0]} - {cust['Loyalty'].values[0]} Tier**\nPoints: {cust['Points'].values[0]}\nSubmit Status: {get_submit_flag()}"

def recommend_items(customer_id):
    cust = customers_df[customers_df["CustomerID"]==customer_id]
    if cust.empty: return "❌ Customer not found"
    history = cust["History"].values[0].split(",")
    recs = [p for p in products_df["Name"].tolist() if p not in history]
    random.shuffle(recs)
    return recs[:2]

def sales_history_table():
    return sales_log if not sales_log.empty else pd.DataFrame(columns=["CustomerID","Product","Quantity","Timestamp"])

# ----------------------------
# Charts
# ----------------------------
def top_selling_products_chart(top_n=5):
    if sales_log.empty:
        fig, ax = plt.subplots(); ax.text(0.5,0.5,"No sales yet",ha="center",va="center"); ax.axis("off"); return fig
    df = sales_log.groupby("Product")["Quantity"].sum().sort_values(ascending=False).head(top_n)
    fig, ax = plt.subplots()
    df.plot(kind="bar", color="skyblue", ax=ax)
    ax.set_ylabel("Quantity Sold"); ax.set_title(f"Top {top_n} Selling Products")
    return fig

def sales_over_time_chart(start_date, end_date):
    if sales_log.empty:
        fig, ax = plt.subplots(); ax.text(0.5,0.5,"No sales yet",ha="center",va="center"); ax.axis("off"); return fig
    df = sales_log.copy(); df["Timestamp"] = pd.to_datetime(df["Timestamp"])
    mask = (df["Timestamp"] >= pd.to_datetime(start_date)) & (df["Timestamp"] <= pd.to_datetime(end_date))
    df_filtered = df[mask]
    if df_filtered.empty:
        fig, ax = plt.subplots(); ax.text(0.5,0.5,"No sales in range",ha="center",va="center"); ax.axis("off"); return fig
    df_grouped = df_filtered.groupby("Timestamp")["Quantity"].sum()
    fig, ax = plt.subplots()
    df_grouped.plot(kind="line", marker="o", color="orange", ax=ax)
    ax.set_ylabel("Quantity Sold"); ax.set_title(f"Sales from {start_date} to {end_date}")
    return fig

def loyalty_distribution_chart(tiers=["Gold","Silver"]):
    df = customers_df[customers_df["Loyalty"].isin(tiers)]["Loyalty"].value_counts()
    if df.empty: fig, ax = plt.subplots(); ax.text(0.5,0.5,"No data",ha="center",va="center"); ax.axis("off"); return fig
    fig, ax = plt.subplots()
    df.plot(kind="pie", autopct="%1.1f%%", colors=["gold","silver","lightgreen"], ax=ax)
    ax.set_ylabel(""); ax.set_title("Loyalty Distribution")
    return fig

# ----------------------------
# Gradio Interface
# ----------------------------
with gr.Blocks() as demo:
    gr.Markdown("## 🌟 Retail Master Dashboard - Interactive & Attractive")

    with gr.Row():
        submit_btn = gr.Button("Submit Assignment")
        submit_status = gr.Textbox(value=get_submit_flag(), label="Submit Status")
        submit_btn.click(update_submit_flag, inputs=None, outputs=submit_status)

    summary_btn = gr.Button("Refresh Dashboard Summary")
    summary_md = gr.Markdown()
    summary_btn.click(dashboard_summary, inputs=None, outputs=summary_md)

    with gr.Tabs():
        with gr.Tab("Analytics"):
            cid_input = gr.Textbox(label="Customer ID", value="C001")
            gr.Button("Check Analytics").click(check_analytics, inputs=cid_input, outputs=gr.Markdown())

        with gr.Tab("Loyalty"):
            cid_input2 = gr.Textbox(label="Customer ID", value="C001")
            gr.Button("Check Loyalty").click(check_loyalty, inputs=cid_input2, outputs=gr.Markdown())

        with gr.Tab("Place Order"):
            cid_input3 = gr.Textbox(label="Customer ID", value="C001")
            item_input = gr.Dropdown(products_df["Name"].tolist(), label="Item")
            qty_input = gr.Slider(1,10,1,label="Quantity")
            gr.Button("Place Order").click(place_order, inputs=[cid_input3,item_input,qty_input], outputs=gr.Markdown())

        with gr.Tab("Recommendations"):
            cid_input4 = gr.Textbox(label="Customer ID", value="C001")
            gr.Button("Get Recommendations").click(recommend_items, inputs=cid_input4, outputs=gr.Markdown())

        with gr.Tab("Sales Log"):
            gr.Button("View Sales Log").click(sales_history_table, inputs=None, outputs=gr.Dataframe())

        with gr.Tab("Charts"):
            top_n_slider = gr.Slider(1,len(products_df),5,step=1,label="Top N Products")
            gr.Button("Top Selling Products").click(top_selling_products_chart, inputs=top_n_slider, outputs=gr.Plot())
            start_date = gr.Textbox(label="Start Date (YYYY-MM-DD)", value="2025-09-26")
            end_date = gr.Textbox(label="End Date (YYYY-MM-DD)", value="2025-09-30")
            gr.Button("Sales Over Time").click(sales_over_time_chart, inputs=[start_date,end_date], outputs=gr.Plot())
            tier_checkbox = gr.CheckboxGroup(["Gold","Silver"], value=["Gold","Silver"], label="Select Tiers")
            gr.Button("Loyalty Distribution").click(loyalty_distribution_chart, inputs=tier_checkbox, outputs=gr.Plot())

demo.launch(share=True)

