import nbformat

path = "Copy_of_Untitled2.ipynb"
nb = nbformat.read(path, as_version=4)

# Remove ALL metadata at notebook level
nb['metadata'] = {}

# Also clean each cell metadata
for cell in nb['cells']:
    cell['metadata'] = {}

nbformat.write(nb, "clean_notebook.ipynb")
print("✅ Fully cleaned notebook saved as clean_notebook.ipynb")

